{
  "name": "Voyage Ledger - Travel Agency ERP",
  "description": "A comprehensive accounting and management software for travel agencies featuring AI-powered financial analysis, booking tracking, and automated invoicing.",
  "requestFramePermissions": [
    "camera"
  ]
