import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) throw new Error("Could not find root element");

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum BookingStatus {
  CONFIRMED = 'CONFIRMED',
  PENDING = 'PENDING',
  CANCELLED = 'CANCELLED'
}

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE'
}

export interface Booking {
  id: string;
  clientName: string;
  type: 'Air Ticket' | 'Hotel' | 'Visa' | 'Package';
  date: string;
  amount: number;
  cost: number;
  status: BookingStatus;
  description: string;
}

export interface Transaction {
  id: string;
  date: string;
  category: string;
  amount: number;
  type: TransactionType;
  bookingId?: string;
  reference: string;
}

export interface AgencyStats {
  totalSales: number;
  totalCost: number;
  netProfit: number;
  pendingInvoices: number;
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Ticket, 
  Receipt, 
  Users, 
  Settings, 
  Plus, 
  TrendingUp, 
  CreditCard, 
  MessageSquareText,
  Search,
  ChevronRight,
  Menu,
  X
} from 'lucide-react';
import { Booking, BookingStatus, Transaction, TransactionType } from './types';
import Dashboard from './components/Dashboard';
import BookingList from './components/BookingList';
import TransactionList from './components/TransactionList';
import AIChat from './components/AIChat';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'bookings' | 'accounts' | 'ai'>('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(true);

  // Initial Mock Data
  const [bookings, setBookings] = useState<Booking[]>([
    { id: '1', clientName: 'Abdur Rahman', type: 'Air Ticket', date: '2024-05-15', amount: 85000, cost: 78000, status: BookingStatus.CONFIRMED, description: 'DAC-DXB-DAC Emirates' },
    { id: '2', clientName: 'Nusrat Jahan', type: 'Visa', date: '2024-05-16', amount: 15000, cost: 12000, status: BookingStatus.PENDING, description: 'Schengen Visa Processing' },
    { id: '3', clientName: 'Karim Ullah', type: 'Hotel', date: '2024-05-17', amount: 45000, cost: 38000, status: BookingStatus.CONFIRMED, description: 'Burj Al Arab 2 Nights' },
  ]);

  const [transactions, setTransactions] = useState<Transaction[]>([
    { id: 't1', date: '2024-05-15', category: 'Ticket Sale', amount: 85000, type: TransactionType.INCOME, reference: 'REF-001' },
    { id: 't2', date: '2024-05-15', category: 'BSP Payment', amount: 78000, type: TransactionType.EXPENSE, reference: 'IATA-88' },
  ]);

  const stats = useMemo(() => {
    const totalSales = bookings.reduce((sum, b) => sum + b.amount, 0);
    const totalCost = bookings.reduce((sum, b) => sum + b.cost, 0);
    const netProfit = totalSales - totalCost;
    const pendingCount = bookings.filter(b => b.status === BookingStatus.PENDING).length;

    return { totalSales, totalCost, netProfit, pendingInvoices: pendingCount };
  }, [bookings]);

  const addBooking = (newBooking: Omit<Booking, 'id'>) => {
    const id = Math.random().toString(36).substr(2, 9);
    setBookings(prev => [...prev, { ...newBooking, id }]);

    // Auto-generate transaction
    const transId = 't' + Math.random().toString(36).substr(2, 5);
    setTransactions(prev => [...prev, {
      id: transId,
      date: new Date().toISOString().split('T')[0],
      category: `${newBooking.type} Sale`,
      amount: newBooking.amount,
      type: TransactionType.INCOME,
      reference: `AUTO-${id}`
    }]);
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      {/* Sidebar */}
      <aside className={`${isSidebarOpen ? 'w-64' : 'w-20'} bg-white border-r border-slate-200 transition-all duration-300 flex flex-col z-50`}>
        <div className="p-6 flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg">
            <Ticket className="text-white w-6 h-6" />
          </div>
          {isSidebarOpen && <h1 className="font-bold text-xl tracking-tight text-slate-800">VoyageLedger</h1>}
        </div>

        <nav className="flex-1 px-4 space-y-1">
          <NavItem 
            icon={<LayoutDashboard />} 
            label="Dashboard" 
            active={activeTab === 'dashboard'} 
            onClick={() => setActiveTab('dashboard')} 
            collapsed={!isSidebarOpen} 
          />
          <NavItem 
            icon={<Ticket />} 
            label="Bookings" 
            active={activeTab === 'bookings'} 
            onClick={() => setActiveTab('bookings')} 
            collapsed={!isSidebarOpen} 
          />
          <NavItem 
            icon={<CreditCard />} 
            label="Accounts" 
            active={activeTab === 'accounts'} 
            onClick={() => setActiveTab('accounts')} 
            collapsed={!isSidebarOpen} 
          />
          <NavItem 
            icon={<MessageSquareText />} 
            label="AI Assistant" 
            active={activeTab === 'ai'} 
            onClick={() => setActiveTab('ai')} 
            collapsed={!isSidebarOpen} 
          />
        </nav>

        <div className="p-4 border-t border-slate-100">
           <NavItem 
            icon={<Settings />} 
            label="Settings" 
            active={false} 
            onClick={() => {}} 
            collapsed={!isSidebarOpen} 
          />
          <button 
            onClick={() => setSidebarOpen(!isSidebarOpen)}
            className="mt-4 w-full flex items-center justify-center p-2 text-slate-400 hover:text-indigo-600 transition-colors"
          >
            {isSidebarOpen ? <X size={20}/> : <Menu size={20}/>}
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0">
          <div className="relative w-96">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
            <input 
              type="text" 
              placeholder="Search bookings, invoices, clients..." 
              className="w-full pl-10 pr-4 py-2 bg-slate-100 rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
            />
          </div>
          <div className="flex items-center gap-4">
            <button className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-indigo-700 transition-colors text-sm font-medium shadow-sm">
              <Plus size={18} />
              New Booking
            </button>
            <div className="w-10 h-10 rounded-full bg-slate-200 border-2 border-white shadow-sm overflow-hidden">
              <img src="https://picsum.photos/40/40" alt="Avatar" />
            </div>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-8">
          {activeTab === 'dashboard' && <Dashboard stats={stats} bookings={bookings} />}
          {activeTab === 'bookings' && <BookingList bookings={bookings} onAdd={addBooking} />}
          {activeTab === 'accounts' && <TransactionList transactions={transactions} stats={stats} />}
          {activeTab === 'ai' && <AIChat bookings={bookings} transactions={transactions} />}
        </div>
      </main>
    </div>
  );
};

const NavItem = ({ icon, label, active, onClick, collapsed }: any) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all duration-200 group ${
      active 
        ? 'bg-indigo-50 text-indigo-700' 
        : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'
    }`}
  >
    <span className={`${active ? 'text-indigo-600' : 'text-slate-400 group-hover:text-slate-600'}`}>
      {React.cloneElement(icon, { size: 20 })}
    </span>
    {!collapsed && <span className="font-medium text-sm">{label}</span>}
    {active && !collapsed && <div className="ml-auto w-1.5 h-1.5 rounded-full bg-indigo-600"></div>}
  </button>
);

export default App;

import React from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar } from 'recharts';
