import { DollarSign, UserCheck, Clock, TrendingUp, ArrowUpRight, ArrowDownRight } from 'lucide-react';

interface Props {
  stats: AgencyStats;
  bookings: Booking[];
}

const Dashboard: React.FC<Props> = ({ stats, bookings }) => {
