const StatCard = ({ label, value, icon, trend, color }: any) => (
  <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
    <div className="flex items-start justify-between mb-4">
      <div className={`p-3 rounded-xl ${color}`}>
        {icon}
      </div>
      <div className="flex items-center gap-1 text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full text-[10px] font-bold">
        <ArrowUpRight size={12} />
        {trend}
      </div>
    </div>
    <p className="text-slate-500 text-sm font-medium mb-1">{label}</p>
    <h4 className="text-2xl font-bold text-slate-900">{value}</h4>
  </div>
);

const StatusBadge = ({ status }: { status: BookingStatus }) => {
  const styles = {
    [BookingStatus.CONFIRMED]: 'bg-emerald-50 text-emerald-600',
    [BookingStatus.PENDING]: 'bg-amber-50 text-amber-600',
    [BookingStatus.CANCELLED]: 'bg-rose-50 text-rose-600',
  };
  return (
    <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wider ${styles[status]}`}>
      {status}
    </span>
  );
};

export default Dashboard;

import { GoogleGenAI } from "@google/genai";
import { Booking, Transaction } from "../types";

export const analyzeAgencyData = async (bookings: Booking[], transactions: Transaction[], query: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const prompt = `
    You are an AI Travel Agency Accounting Expert. 
    Analyze the following data and answer the user query:

    Agency Data:
    - Current Bookings: ${JSON.stringify(bookings)}
    - Transaction History: ${JSON.stringify(transactions)}

    User Query: ${query}

    Please provide professional, actionable insights in English or Bengali as per the user's language. 
    Focus on profit optimization, pending tasks, and financial health.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("AI Analysis Error:", error);
    return "I am having trouble analyzing the data right now. Please try again later.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Send, Sparkles, Bot, User, Loader2 } from 'lucide-react';
import { analyzeAgencyData } from '../services/gemini';
import { Booking, Transaction } from '../types';

interface Message {
  role: 'user' | 'ai';
  content: string;
}

interface Props {
  bookings: Booking[];
  transactions: Transaction[];
}

const AIChat: React.FC<Props> = ({ bookings, transactions }) => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'ai', content: 'Hello! I am your AI Agency Advisor. Ask me anything about your agency sales, profit, or pending bookings. (আপনি বাংলাতেও প্রশ্ন করতে পারেন)' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setLoading(true);

    const aiResponse = await analyzeAgencyData(bookings, transactions, userMsg);

    setMessages(prev => [...prev, { role: 'ai', content: aiResponse || 'No response from AI.' }]);
    setLoading(false);
  };

  return (
    <div className="flex flex-col h-full max-w-4xl mx-auto bg-white rounded-2xl border border-slate-200 shadow-xl overflow-hidden animate-in zoom-in-95 duration-300">
      <div className="p-6 border-b border-slate-100 flex items-center gap-3 bg-indigo-600 text-white">
        <div className="bg-indigo-500 p-2 rounded-xl">
          <Sparkles size={20} />
        </div>
        <div>
          <h2 className="font-bold">AI Financial Advisor</h2>
          <p className="text-xs text-indigo-100">Powered by Gemini AI • Real-time Data Analytics</p>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/50">
        {messages.map((m, i) => (
          <div key={i} className={`flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 shadow-sm ${
              m.role === 'ai' ? 'bg-white text-indigo-600' : 'bg-indigo-600 text-white'
            }`}>
              {m.role === 'ai' ? <Bot size={20} /> : <User size={20} />}
            </div>
            <div className={`max-w-[80%] p-4 rounded-2xl shadow-sm text-sm leading-relaxed whitespace-pre-wrap ${
              m.role === 'ai' ? 'bg-white text-slate-700 rounded-tl-none' : 'bg-indigo-600 text-white rounded-tr-none'
            }`}>
              {m.content}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex gap-4">
            <div className="w-10 h-10 rounded-2xl bg-white text-indigo-600 flex items-center justify-center shrink-0 shadow-sm">
              <Bot size={20} />
            </div>
            <div className="bg-white p-4 rounded-2xl shadow-sm rounded-tl-none flex items-center gap-2">
              <Loader2 className="animate-spin text-indigo-600" size={16} />
              <span className="text-sm text-slate-400">Thinking...</span>
            </div>
          </div>
        )}
      </div>

      <div className="p-6 border-t border-slate-100 bg-white">
        <div className="flex gap-4">
          <input 
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
            placeholder="Type your question (e.g., What is my total profit this month?)"
            className="flex-1 px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500/20 outline-none text-sm transition-all"
          />
          <button 
            onClick={handleSend}
            disabled={loading}
            className="bg-indigo-600 text-white p-3 rounded-xl hover:bg-indigo-700 disabled:opacity-50 shadow-lg shadow-indigo-100 transition-all active:scale-95"
          >
            <Send size={20} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default AIChat;

