import React, { useState, useRef, useEffect } from 'react';
import { Send, Sparkles, Bot, User, Loader2 } from 'lucide-react';
import { analyzeAgencyData } from '../services/gemini';
import { Booking, Transaction } from '../types';

interface Message {
  role: 'user' | 'ai';
  content: string;
}

interface Props {
  bookings: Booking[];
  transactions: Transaction[];
  isDarkMode?: boolean;
}

const AIChat: React.FC<Props> = ({ bookings, transactions, isDarkMode }) => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'ai', content: 'Hello! I am your AI Agency Advisor. Ask me anything about your agency sales, profit, or pending bookings. (আপনি বাংলাতেও প্রশ্ন করতে পারেন)' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setLoading(true);

    const aiResponse = await analyzeAgencyData(bookings, transactions, userMsg);

    setMessages(prev => [...prev, { role: 'ai', content: aiResponse || 'No response from AI.' }]);
    setLoading(false);
  };

  return (
    <div className={`flex flex-col h-full max-w-4xl mx-auto rounded-2xl border shadow-xl overflow-hidden animate-in zoom-in-95 duration-300 transition-colors ${
      isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'
    }`}>
      <div className={`p-4 md:p-6 border-b flex items-center gap-3 bg-indigo-600 text-white`}>
        <div className="bg-indigo-500 p-2 rounded-xl">
          <Sparkles size={20} />
        </div>
        <div>
          <h2 className="font-bold text-sm md:text-base">AI Financial Advisor</h2>
          <p className="text-[10px] md:text-xs text-indigo-100">Powered by Gemini AI • Real-time Data Analytics</p>
        </div>
      </div>

      <div ref={scrollRef} className={`flex-1 overflow-y-auto p-4 md:p-6 space-y-6 ${isDarkMode ? 'bg-slate-950/30' : 'bg-slate-50/50'}`}>
        {messages.map((m, i) => (
          <div key={i} className={`flex gap-3 md:gap-4 ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
            <div className={`w-8 h-8 md:w-10 md:h-10 rounded-2xl flex items-center justify-center shrink-0 shadow-sm ${
              m.role === 'ai' 
                ? isDarkMode ? 'bg-slate-800 text-indigo-400' : 'bg-white text-indigo-600' 
                : 'bg-indigo-600 text-white'
            }`}>
              {m.role === 'ai' ? <Bot size={18} /> : <User size={18} />}
            </div>
            <div className={`max-w-[85%] p-3 md:p-4 rounded-2xl shadow-sm text-xs md:text-sm leading-relaxed whitespace-pre-wrap ${
              m.role === 'ai' 
                ? isDarkMode ? 'bg-slate-800 text-slate-200 rounded-tl-none border border-slate-700/50' : 'bg-white text-slate-700 rounded-tl-none border border-slate-100'
                : 'bg-indigo-600 text-white rounded-tr-none'
            }`}>
              {m.content}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex gap-4">
            <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 shadow-sm ${
              isDarkMode ? 'bg-slate-800 text-indigo-400' : 'bg-white text-indigo-600'
            }`}>
              <Bot size={20} />
            </div>
            <div className={`p-4 rounded-2xl shadow-sm rounded-tl-none flex items-center gap-2 border ${
              isDarkMode ? 'bg-slate-800 border-slate-700 text-slate-400' : 'bg-white border-slate-100 text-slate-400'
            }`}>
              <Loader2 className="animate-spin text-indigo-600" size={16} />
              <span className="text-sm">Thinking...</span>
            </div>
          </div>
        )}
      </div>

      <div className={`p-4 md:p-6 border-t transition-colors ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
        <div className="flex gap-3 md:gap-4">
          <input 
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
            placeholder="Type your question..."
            className={`flex-1 px-4 py-2.5 md:py-3 border rounded-xl focus:ring-2 focus:ring-indigo-500/20 outline-none text-xs md:text-sm transition-all ${
              isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
            }`}
          />
          <button 
            onClick={handleSend}
            disabled={loading}
            className="bg-indigo-600 text-white p-2.5 md:p-3 rounded-xl hover:bg-indigo-700 disabled:opacity-50 shadow-lg shadow-indigo-100 dark:shadow-none transition-all active:scale-95"
          >
            <Send size={20} />
          </button>
        </div>
      </div>
    </div>
  );
};

