                        booking.type === 'Air Ticket' ? isDarkMode ? 'bg-blue-900/30 text-blue-400' : 'bg-blue-50 text-blue-600' :
                        booking.type === 'Hotel' ? isDarkMode ? 'bg-amber-900/30 text-amber-400' : 'bg-amber-50 text-amber-600' :
                        isDarkMode ? 'bg-purple-900/30 text-purple-400' : 'bg-purple-50 text-purple-600'
                      }`}>
                        <FileText size={16} />
                      </div>
                      <div className="min-w-0">
                        <p className={`font-semibold text-sm truncate ${isDarkMode ? 'text-slate-200' : 'text-slate-800'}`}>{booking.clientName}</p>
                        <p className="text-xs text-slate-500 truncate">{booking.description}</p>
                      </div>
                    </div>
                  </td>
                  <td className={`px-6 py-4 text-sm ${isDarkMode ? 'text-slate-400' : 'text-slate-600'}`}>{booking.date}</td>
                  <td className="px-6 py-4">
                    <p className={`font-bold text-sm ${isDarkMode ? 'text-slate-100' : 'text-slate-800'}`}>৳{booking.amount.toLocaleString()}</p>
                  </td>
                  <td className="px-6 py-4">
                    <p className={`font-bold text-sm ${isDarkMode ? 'text-emerald-400' : 'text-emerald-600'}`}>+৳{(booking.amount - booking.cost).toLocaleString()}</p>
                  </td>
                  <td className="px-6 py-4">
                    <StatusBadge status={booking.status} isDarkMode={isDarkMode} />
                  </td>
                  <td className="px-6 py-4 text-right">
                    <button 
                      onClick={(e) => { e.stopPropagation(); /* Prevents triggering row click */ }}
                      className={`p-2 rounded-lg transition-colors ${isDarkMode ? 'text-slate-500 hover:bg-slate-700 hover:text-slate-300' : 'text-slate-400 hover:bg-slate-200 hover:text-slate-600'}`}
                    >
                      <MoreVertical size={16} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Detail View Modal */}
      {selectedBooking && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className={`rounded-3xl w-full max-w-2xl shadow-2xl animate-in zoom-in-95 duration-200 overflow-hidden ${
            isDarkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'
          }`}>
            <div className={`px-8 py-6 border-b flex items-center justify-between ${
              isDarkMode ? 'bg-slate-800/50 border-slate-800' : 'bg-slate-50/50 border-slate-100'
            }`}>
              <div className="flex items-center gap-3">
                <div className={`p-2.5 rounded-2xl ${isDarkMode ? 'bg-indigo-900/40 text-indigo-400' : 'bg-indigo-50 text-indigo-600'}`}>
                  <Info size={24} />
                </div>
                <div>
                  <h3 className="font-bold text-lg">Booking Details</h3>
                  <p className="text-xs text-slate-500">Transaction ID: {selectedBooking.id.toUpperCase()}</p>
                </div>
              </div>
              <button 
                onClick={() => setSelectedBooking(null)} 
                className={`p-2 rounded-xl transition-colors ${isDarkMode ? 'hover:bg-slate-800 text-slate-400' : 'hover:bg-slate-100 text-slate-500'}`}
              >
                <X size={20} />
              </button>
            </div>

            <div className="p-8 grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-2">Customer Information</label>
                  <div className={`p-4 rounded-2xl border ${isDarkMode ? 'bg-slate-800/50 border-slate-700' : 'bg-slate-50 border-slate-200'}`}>
                    <h4 className="font-bold text-base mb-1">{selectedBooking.clientName}</h4>
                    {(() => {
                      const client = getClientDetails(selectedBooking.clientId);
                      return (
                        <div className="space-y-2 mt-3">
                          <div className="flex items-center gap-2 text-sm text-slate-500">
                            <Mail size={14} className="shrink-0" />
                            <span className="truncate">{client?.email || 'No email registered'}</span>
                          </div>
                          <div className="flex items-center gap-2 text-sm text-slate-500">
                            <Phone size={14} className="shrink-0" />
                            <span>{client?.phone || 'No phone registered'}</span>
                          </div>
                          <div className="flex items-start gap-2 text-sm text-slate-500 pt-2 border-t border-slate-200 dark:border-slate-700 mt-2">
                            <MapPin size={14} className="shrink-0 mt-0.5" />
                            <span className="leading-relaxed">{client?.address || 'No address provided'}</span>
                          </div>
                        </div>
                      );
                    })()}
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-2">Service Type</label>
                  <div className="flex items-center gap-3">
                    <div className={`px-4 py-2 rounded-xl text-sm font-bold ${
                      selectedBooking.type === 'Air Ticket' ? 'bg-blue-100 text-blue-700' :
                      selectedBooking.type === 'Hotel' ? 'bg-amber-100 text-amber-700' :
                      'bg-purple-100 text-purple-700'
                    }`}>
                      {selectedBooking.type}
                    </div>
                    <span className="text-sm text-slate-500 font-medium">Date: {selectedBooking.date}</span>
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-2">Financial Breakdown</label>
                  <div className={`divide-y ${isDarkMode ? 'divide-slate-800' : 'divide-slate-100'}`}>
                    <div className="py-2 flex justify-between items-center">
                      <span className="text-sm text-slate-500">Selling Price</span>
                      <span className="font-bold">৳{selectedBooking.amount.toLocaleString()}</span>
                    </div>
                    <div className="py-2 flex justify-between items-center">
                      <span className="text-sm text-slate-500">Agent Cost</span>
                      <span className="font-bold text-rose-500">৳{selectedBooking.cost.toLocaleString()}</span>
                    </div>
                    <div className="py-2 flex justify-between items-center">
                      <span className="text-sm font-bold text-slate-800 dark:text-slate-200">Net Profit</span>
                      <span className="font-bold text-emerald-500 text-lg">৳{(selectedBooking.amount - selectedBooking.cost).toLocaleString()}</span>
                    </div>
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-2">Notes & Description</label>
                  <div className={`p-4 rounded-2xl text-sm leading-relaxed ${isDarkMode ? 'bg-slate-800 text-slate-300' : 'bg-slate-100 text-slate-600'}`}>
                    {selectedBooking.description || 'No additional notes provided for this booking.'}
                  </div>
                </div>

                <div className="pt-2">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-2">Current Status</label>
                  <div className="flex">
                    <StatusBadge status={selectedBooking.status} isDarkMode={isDarkMode} />
                  </div>
                </div>
              </div>
            </div>

            <div className={`px-8 py-6 flex gap-3 ${isDarkMode ? 'bg-slate-800/30' : 'bg-slate-50'}`}>
              <button 
                onClick={() => setSelectedBooking(null)}
                className={`flex-1 py-3 text-sm font-bold rounded-2xl transition-all ${
                  isDarkMode ? 'bg-slate-800 text-slate-300 hover:bg-slate-700' : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 shadow-sm'
                }`}
              >
                Close
              </button>
              <button 
                className="flex-1 py-3 bg-indigo-600 text-white text-sm font-bold rounded-2xl shadow-lg shadow-indigo-500/20 hover:bg-indigo-700 transition-all"
              >
                Print Invoice
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Create Modal Overlay */}
      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className={`rounded-2xl w-full max-w-lg shadow-2xl animate-in zoom-in-95 duration-200 overflow-hidden ${
            isDarkMode ? 'bg-slate-900 text-white' : 'bg-white text-slate-900'
          }`}>
            <div className={`px-6 py-4 border-b flex items-center justify-between ${
              isDarkMode ? 'bg-slate-800/50 border-slate-800' : 'bg-slate-50/50 border-slate-100'
            }`}>
              <h3 className="font-bold">Create New Booking</h3>
              <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-600">
                <Plus className="rotate-45" />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Select Client</label>
                  <select 
                    required
                    value={formData.clientId}
                    onChange={e => handleClientChange(e.target.value)}
                    className={`w-full px-4 py-2 border rounded-xl outline-none text-sm ${
                      isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                    }`}>
                    <option value="">-- Choose Existing Client --</option>
                    {clients.map(c => (
                      <option key={c.id} value={c.id}>{c.name} ({c.phone})</option>
                    ))}
                  </select>
                </div>
                {!formData.clientId && (
                  <div className="col-span-2">
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Or Enter New Client Name</label>
                    <input 
                      required
                      value={formData.clientName}
                      onChange={e => setFormData({...formData, clientName: e.target.value})}
                      type="text" className={`w-full px-4 py-2 border rounded-xl focus:ring-2 focus:ring-indigo-500/20 outline-none text-sm transition-all ${
                        isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                      }`} />
                  </div>
                )}
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Type</label>
                  <select 
                    value={formData.type}
                    onChange={e => setFormData({...formData, type: e.target.value as any})}
                    className={`w-full px-4 py-2 border rounded-xl outline-none text-sm ${
                      isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                    }`}>
                    <option>Air Ticket</option>
                    <option>Hotel</option>
                    <option>Visa</option>
                    <option>Package</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Date</label>
                  <input 
                    type="date" 
                    value={formData.date}
                    onChange={e => setFormData({...formData, date: e.target.value})}
                    className={`w-full px-4 py-2 border rounded-xl outline-none text-sm ${
                      isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                    }`} />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Selling Price (৳)</label>
                  <input 
                    required
                    type="number" 
                    value={formData.amount}
                    onChange={e => setFormData({...formData, amount: Number(e.target.value)})}
                    className={`w-full px-4 py-2 border rounded-xl outline-none text-sm ${
                      isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                    }`} />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Agent Cost (৳)</label>
                  <input 
                    required
                    type="number" 
                    value={formData.cost}
                    onChange={e => setFormData({...formData, cost: Number(e.target.value)})}
                    className={`w-full px-4 py-2 border rounded-xl outline-none text-sm ${
                      isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                    }`} />
                </div>
                <div className="col-span-2">
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Description</label>
                  <textarea 
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                    className={`w-full px-4 py-2 border rounded-xl outline-none text-sm h-20 resize-none ${
                      isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                    }`} />
                </div>
              </div>
              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setShowModal(false)} className={`flex-1 py-2.5 text-sm font-bold rounded-xl transition-all ${
                  isDarkMode ? 'text-slate-400 hover:bg-slate-800' : 'text-slate-500 hover:bg-slate-50'
                }`}>Cancel</button>
                <button type="submit" className="flex-1 py-2.5 bg-indigo-600 text-white text-sm font-bold rounded-xl shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-all">Save Booking</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status, isDarkMode }: { status: BookingStatus, isDarkMode?: boolean }) => {
  const styles = {
    [BookingStatus.CONFIRMED]: isDarkMode ? 'bg-emerald-900/30 text-emerald-400 border-emerald-800/40' : 'bg-emerald-50 text-emerald-600 border-emerald-100',
    [BookingStatus.PENDING]: isDarkMode ? 'bg-amber-900/30 text-amber-400 border-amber-800/40' : 'bg-amber-50 text-amber-600 border-amber-100',
    [BookingStatus.CANCELLED]: isDarkMode ? 'bg-rose-900/30 text-rose-400 border-rose-800/40' : 'bg-rose-50 text-rose-600 border-rose-100',
  };
  return (
    <span className={`text-[10px] px-2.5 py-1 rounded-full font-bold uppercase tracking-wider border ${styles[status]}`}>
      {status}
    </span>
  );
};

export default BookingList;

import React, { useState, useMemo } from 'react';
import { Booking, BookingStatus, Client } from '../types';
import { Search, Filter, Plus, FileText, MoreVertical, User, MapPin, Phone, Mail, X, Info, RotateCcw, ArrowUpDown } from 'lucide-react';

interface Props {
  bookings: Booking[];
  clients: Client[];
  onAdd: (booking: Omit<Booking, 'id'>) => void;
  isDarkMode?: boolean;
}

const BookingList: React.FC<Props> = ({ bookings, clients, onAdd, isDarkMode }) => {
  const [showModal, setShowModal] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null);

  // Filter and Sort State
  const [filters, setFilters] = useState({
    status: '' as string,
    clientId: '' as string,
    date: '' as string,
    sortOrder: 'desc' as 'asc' | 'desc'
  });

  const [formData, setFormData] = useState({
    clientId: '',
    clientName: '',
    type: 'Air Ticket' as any,
    date: new Date().toISOString().split('T')[0],
    amount: 0,
    cost: 0,
    status: BookingStatus.PENDING,
    description: ''
  });

  const handleClientChange = (clientId: string) => {
    const client = clients.find(c => c.id === clientId);
    if (client) {
      setFormData({ ...formData, clientId, clientName: client.name });
    } else {
      setFormData({ ...formData, clientId: '', clientName: '' });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAdd(formData);
    setShowModal(false);
    setFormData({
      clientId: '',
      clientName: '',
      type: 'Air Ticket',
      date: new Date().toISOString().split('T')[0],
      amount: 0,
      cost: 0,
      status: BookingStatus.PENDING,
      description: ''
    });
  };

  const getClientDetails = (clientId?: string) => {
    return clients.find(c => c.id === clientId);
  };

  const filteredAndSortedBookings = useMemo(() => {
    return bookings
      .filter(booking => {
        const matchesStatus = !filters.status || booking.status === filters.status;
        const matchesClient = !filters.clientId || booking.clientId === filters.clientId;
        const matchesDate = !filters.date || booking.date === filters.date;
        return matchesStatus && matchesClient && matchesDate;
      })
      .sort((a, b) => {
        const dateA = new Date(a.date).getTime();
        const dateB = new Date(b.date).getTime();
        return filters.sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
      });
  }, [bookings, filters]);

  const clearFilters = () => {
    setFilters({
      status: '',
      clientId: '',
      date: '',
      sortOrder: 'desc'
    });
  };

  const isFilterActive = filters.status || filters.clientId || filters.date || filters.sortOrder !== 'desc';

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
        <div>
          <h2 className={`text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-slate-800'}`}>Booking Inventory</h2>
          <p className={`${isDarkMode ? 'text-slate-400' : 'text-slate-500'} text-sm`}>Manage and track all customer travel requests</p>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`flex items-center gap-2 px-4 py-2 border rounded-xl text-sm font-medium transition-all shadow-sm ${
              showFilters 
                ? 'bg-indigo-600 border-indigo-600 text-white' 
                : isDarkMode ? 'bg-slate-900 border-slate-700 text-slate-300 hover:bg-slate-800' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
            }`}
          >
            <Filter size={18} />
            {showFilters ? 'Hide Filters' : 'Filters'}
          </button>
          <button 
            onClick={() => setShowModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 text-sm font-medium shadow-sm transition-colors"
          >
            <Plus size={18} />
            Create Booking
          </button>
        </div>
      </div>

      {/* Filter Panel */}
      {showFilters && (
        <div className={`mb-6 p-6 rounded-2xl border animate-in slide-in-from-top-4 duration-300 ${
          isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'
        } shadow-sm`}>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4 items-end">
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Status</label>
              <select 
                value={filters.status}
                onChange={(e) => setFilters({...filters, status: e.target.value})}
                className={`w-full px-3 py-2 border rounded-xl outline-none text-sm ${
                  isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                }`}
              >
                <option value="">All Statuses</option>
                <option value={BookingStatus.CONFIRMED}>Confirmed</option>
                <option value={BookingStatus.PENDING}>Pending</option>
                <option value={BookingStatus.CANCELLED}>Cancelled</option>
              </select>
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Client</label>
              <select 
                value={filters.clientId}
                onChange={(e) => setFilters({...filters, clientId: e.target.value})}
                className={`w-full px-3 py-2 border rounded-xl outline-none text-sm ${
                  isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                }`}
              >
                <option value="">All Clients</option>
                {clients.map(c => (
                  <option key={c.id} value={c.id}>{c.name}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Travel Date</label>
              <input 
                type="date"
                value={filters.date}
                onChange={(e) => setFilters({...filters, date: e.target.value})}
                className={`w-full px-3 py-2 border rounded-xl outline-none text-sm ${
                  isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                }`}
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">Sort By Date</label>
              <select 
                value={filters.sortOrder}
                onChange={(e) => setFilters({...filters, sortOrder: e.target.value as 'asc' | 'desc'})}
                className={`w-full px-3 py-2 border rounded-xl outline-none text-sm ${
                  isDarkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200 text-slate-900'
                }`}
              >
                <option value="desc">Newest First</option>
                <option value="asc">Oldest First</option>
              </select>
            </div>
            <div>
              <button 
                onClick={clearFilters}
                disabled={!isFilterActive}
                className={`w-full flex items-center justify-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all ${
                  isFilterActive 
                    ? 'bg-rose-50 text-rose-600 hover:bg-rose-100 border border-rose-200' 
                    : 'bg-slate-100 text-slate-400 border border-slate-200 cursor-not-allowed'
                }`}
              >
                <RotateCcw size={16} />
                Clear
              </button>
            </div>
          </div>
        </div>
      )}

      <div className={`rounded-2xl border shadow-sm overflow-hidden transition-colors ${
        isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'
      }`}>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className={`${isDarkMode ? 'bg-slate-800/50 border-slate-700' : 'bg-slate-50/50 border-slate-200'} border-b`}>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Client & Type</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Date</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Selling Price</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Profit</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Status</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider text-right">Actions</th>
              </tr>
            </thead>
            <tbody className={`divide-y ${isDarkMode ? 'divide-slate-800' : 'divide-slate-100'}`}>
              {filteredAndSortedBookings.length > 0 ? (
                filteredAndSortedBookings.map((booking) => (
                  <tr 
                    key={booking.id} 
                    onClick={() => setSelectedBooking(booking)}
                    className={`transition-colors group cursor-pointer ${isDarkMode ? 'hover:bg-slate-800/80' : 'hover:bg-slate-50/80'}`}
                  >
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className={`p-2 rounded-lg ${
