import React, { useState } from 'react';
import { Client, Booking } from '../types';
import { Search, Plus, Mail, Phone, User, MoreVertical, Edit2, Trash2, ExternalLink } from 'lucide-react';

interface Props {
  clients: Client[];
  bookings: Booking[];
  onAdd: (client: Omit<Client, 'id' | 'createdAt'>) => void;
  onUpdate: (client: Client) => void;
  isDarkMode?: boolean;
}

const ClientList: React.FC<Props> = ({ clients, bookings, onAdd, onUpdate, isDarkMode }) => {
  const [showModal, setShowModal] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
