const BookingList: React.FC<Props> = ({ bookings, clients, onAdd, isDarkMode }) => {
  const [showModal, setShowModal] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null);
  const [isPrinting, setIsPrinting] = useState(false);

  // Filter and Sort State
  const [filters, setFilters] = useState({
    status: '' as string,
    clientId: '' as string,
    date: '' as string,
    sortOrder: 'desc' as 'asc' | 'desc'
  });

  const [formData, setFormData] = useState({
    clientId: '',
    clientName: '',
    type: 'Air Ticket' as any,
    date: new Date().toISOString().split('T')[0],
    amount: 0,
    cost: 0,
    status: BookingStatus.PENDING,
    description: ''
  });

  const handleClientChange = (clientId: string) => {
    const client = clients.find(c => c.id === clientId);
    if (client) {
      setFormData({ ...formData, clientId, clientName: client.name });
    } else {
      setFormData({ ...formData, clientId: '', clientName: '' });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAdd(formData);
    setShowModal(false);
    setFormData({
      clientId: '',
      clientName: '',
      type: 'Air Ticket',
      date: new Date().toISOString().split('T')[0],
      amount: 0,
      cost: 0,
      status: BookingStatus.PENDING,
      description: ''
    });
  };

  const getClientDetails = (clientId?: string) => {
    return clients.find(c => c.id === clientId);
  };

  const filteredAndSortedBookings = useMemo(() => {
    return bookings
      .filter(booking => {
        const matchesStatus = !filters.status || booking.status === filters.status;
        const matchesClient = !filters.clientId || booking.clientId === filters.clientId;
        const matchesDate = !filters.date || booking.date === filters.date;
        return matchesStatus && matchesClient && matchesDate;
      })
      .sort((a, b) => {
        const dateA = new Date(a.date).getTime();
        const dateB = new Date(b.date).getTime();
        return filters.sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
      });
  }, [bookings, filters]);

  const clearFilters = () => {
    setFilters({
      status: '',
      clientId: '',
      date: '',
      sortOrder: 'desc'
    });
  };

  const handlePrintInvoice = (booking: Booking) => {
    const client = getClientDetails(booking.clientId);
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const invoiceHTML = `
      <!DOCTYPE html>
      <html>
      <head>
        <title>Invoice - ${booking.id.toUpperCase()}</title>
        <style>
          @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;700&display=swap');
          body { font-family: 'Inter', sans-serif; padding: 40px; color: #334155; }
          .header { display: flex; justify-content: space-between; border-bottom: 2px solid #e2e8f0; padding-bottom: 20px; margin-bottom: 40px; }
          .logo { font-size: 24px; font-weight: bold; color: #4f46e5; }
          .invoice-info { text-align: right; }
          .details { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; margin-bottom: 40px; }
          .details h3 { font-size: 12px; text-transform: uppercase; color: #94a3b8; margin-bottom: 10px; }
          .table { w-full border-collapse: collapse; margin-bottom: 40px; }
          table { width: 100%; border-collapse: collapse; }
          th { text-align: left; background: #f8fafc; padding: 12px; border-bottom: 1px solid #e2e8f0; font-size: 14px; }
          td { padding: 12px; border-bottom: 1px solid #f1f5f9; font-size: 14px; }
          .totals { margin-left: auto; width: 300px; }
          .total-row { display: flex; justify-content: space-between; padding: 8px 0; }
          .grand-total { border-top: 2px solid #e2e8f0; margin-top: 10px; padding-top: 10px; font-weight: bold; font-size: 18px; color: #1e293b; }
          .footer { margin-top: 60px; font-size: 12px; color: #94a3b8; border-top: 1px solid #f1f5f9; padding-top: 20px; }
          @media print { .no-print { display: none; } }
        </style>
      </head>
      <body>
        <div class="header">
          <div>
            <div class="logo">B2C Ticket Travel Agency</div>
            <p style="font-size: 14px; margin-top: 5px;">House 12, Road 5, Sector 7, Uttara, Dhaka</p>
            <p style="font-size: 14px;">Phone: +880 1234 567 890</p>
          </div>
          <div class="invoice-info">
            <h1 style="margin: 0; color: #1e293b;">INVOICE</h1>
            <p style="font-size: 14px; font-weight: bold;">ID: #${booking.id.toUpperCase()}</p>
            <p style="font-size: 14px;">Date: ${new Date().toLocaleDateString()}</p>
          </div>
        </div>

        <div class="details">
          <div>
            <h3>Bill To:</h3>
            <p style="font-weight: bold; margin: 0;">${booking.clientName}</p>
            <p style="margin: 4px 0;">${client?.email || 'N/A'}</p>
            <p style="margin: 4px 0;">${client?.phone || 'N/A'}</p>
            <p style="margin: 4px 0; font-size: 13px;">${client?.address || 'N/A'}</p>
          </div>
          <div>
            <h3>Payment Details:</h3>
            <p style="margin: 4px 0;">Due Date: ${booking.date}</p>
            <p style="margin: 4px 0;">Status: <strong>${booking.status}</strong></p>
          </div>
        </div>

        <table>
          <thead>
            <tr>
              <th>Description</th>
              <th>Service Type</th>
              <th style="text-align: right;">Amount</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>${booking.description || 'Standard Travel Service'}</td>
              <td>${booking.type}</td>
              <td style="text-align: right;">৳${booking.amount.toLocaleString()}</td>
            </tr>
          </tbody>
        </table>

        <div class="totals">
          <div class="total-row">
            <span>Subtotal</span>
            <span>৳${booking.amount.toLocaleString()}</span>
          </div>
          <div class="total-row">
            <span>Tax (0%)</span>
            <span>৳0</span>
          </div>
          <div class="total-row grand-total">
            <span>Amount Payable</span>
            <span>৳${booking.amount.toLocaleString()}</span>
          </div>
        </div>

        <div class="footer">
          <p><strong>Terms & Conditions:</strong> Tickets and visas are subject to carrier/embassy terms. Refunds are processed within 14 working days.</p>
          <p style="text-align: center; margin-top: 40px;">Thank you for choosing B2C Ticket Travel Agency!</p>
        </div>
      </body>
      </html>
    `;

    printWindow.document.write(invoiceHTML);
    printWindow.document.close();

    // Wait for styles/fonts to load before printing
    printWindow.onload = () => {
      printWindow.print();
      // Optional: close window after print
      // printWindow.close();
    };
