                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Client & Type</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Date</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Selling Price</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Profit</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider">Status</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-400 uppercase tracking-wider text-right">Actions</th>
              </tr>
            </thead>
            <tbody className={`divide-y ${isDarkMode ? 'divide-slate-800' : 'divide-slate-100'}`}>
              {filteredAndSortedBookings.length > 0 ? (
                filteredAndSortedBookings.map((booking) => (
                  <tr 
                    key={booking.id} 
                    onClick={() => setSelectedBooking(booking)}
                    className={`transition-colors group cursor-pointer ${isDarkMode ? 'hover:bg-slate-800/80' : 'hover:bg-slate-50/80'}`}
                  >
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className={`p-2 rounded-lg ${
                          booking.type === 'Air Ticket' ? isDarkMode ? 'bg-blue-900/30 text-blue-400' : 'bg-blue-50 text-blue-600' :
                          booking.type === 'Hotel' ? isDarkMode ? 'bg-amber-900/30 text-amber-400' : 'bg-amber-50 text-amber-600' :
                          isDarkMode ? 'bg-purple-900/30 text-purple-400' : 'bg-purple-50 text-purple-600'
                        }`}>
                          <FileText size={16} />
                        </div>
                        <div className="min-w-0">
                          <p className={`font-semibold text-sm truncate ${isDarkMode ? 'text-slate-200' : 'text-slate-800'}`}>{booking.clientName}</p>
