                    <td className={`px-6 py-4 text-sm ${isDarkMode ? 'text-slate-400' : 'text-slate-600'}`}>{booking.date}</td>
                    <td className="px-6 py-4">
                      <p className={`font-bold text-sm ${isDarkMode ? 'text-slate-100' : 'text-slate-800'}`}>৳{booking.amount.toLocaleString()}</p>
                    </td>
