          </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status, isDarkMode }: { status: BookingStatus, isDarkMode?: boolean }) => {
  const styles = {
    [BookingStatus.CONFIRMED]: isDarkMode ? 'bg-emerald-900/30 text-emerald-400 border-emerald-800/40' : 'bg-emerald-50 text-emerald-600 border-emerald-100',
    [BookingStatus.PENDING]: isDarkMode ? 'bg-amber-900/30 text-amber-400 border-amber-800/40' : 'bg-amber-50 text-amber-600 border-amber-100',
    [BookingStatus.CANCELLED]: isDarkMode ? 'bg-rose-900/30 text-rose-400 border-rose-800/40' : 'bg-rose-50 text-rose-600 border-rose-100',
  };
  return (
    <span className={`text-[10px] px-2.5 py-1 rounded-full font-bold uppercase tracking-wider border ${styles[status]}`}>
      {status}
    </span>
  );
};

