    clientId: '',
    clientName: '',
    type: 'Air Ticket' as any,
    date: new Date().toISOString().split('T')[0],
    amount: 0,
    cost: 0,
    status: BookingStatus.PENDING,
    description: '',
    pnr: '',
    route: ''
