          <div className="flex items-center gap-4">
            <button onClick={() => setActiveTab('accounts')} className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-indigo-700 transition-colors text-sm font-medium">
