);

export default App;

export enum BookingStatus {
  CONFIRMED = 'CONFIRMED',
  PENDING = 'PENDING',
  CANCELLED = 'CANCELLED'
}

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE'
}

export interface Client {
  id: string;
  name: string;
  email: string;
  phone: string;
  passportNumber?: string;
  address?: string;
  createdAt: string;
}

export interface Booking {
  id: string;
  clientId?: string;
  clientName: string;
  clientPhone?: string;
  type: 'Air Ticket' | 'Hotel' | 'Visa' | 'Package';
  date: string; // Booking date
  amount: number;
  cost: number;
  status: BookingStatus;
  description: string;
  pnr?: string;
  route?: string;
  from?: string;
  to?: string;
  flyingDate?: string;
  bookingSource?: string;
}

export interface Transaction {
  id: string;
  date: string;
  category: string;
  amount: number;
  type: TransactionType;
  bookingId?: string;
  reference: string;
}

export interface AgencyStats {
  totalSales: number;
  totalCost: number;
  netProfit: number;
  pendingInvoices: number;
}

import React, { useState, useMemo } from 'react';
import { Booking, BookingStatus, Client } from '../types';
import { 
  Search, Filter, Plus, FileText, MoreVertical, MapPin, 
  Phone, Mail, X, Info, RotateCcw, Download, Plane, 
  PlaneTakeoff, PlaneLanding, Globe, Calendar 
} from 'lucide-react';

interface Props {
  bookings: Booking[];
  clients: Client[];
  onAdd: (booking: Omit<Booking, 'id'>) => void;
  isDarkMode?: boolean;
}

const BookingList: React.FC<Props> = ({ bookings, clients, onAdd, isDarkMode }) => {
  const [showModal, setShowModal] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null);

  const [filters, setFilters] = useState({
    status: '' as string,
    clientId: '' as string,
    date: '' as string,
    sortOrder: 'desc' as 'asc' | 'desc'
  });

  const [formData, setFormData] = useState({
    clientId: '',
    clientName: '',
    clientPhone: '',
    type: 'Air Ticket' as any,
    date: new Date().toISOString().split('T')[0],
    flyingDate: '',
    from: '',
    to: '',
    amount: 0,
    cost: 0,
    status: BookingStatus.PENDING,
    description: '',
    pnr: '',
    bookingSource: ''
  });

  const handleClientChange = (clientId: string) => {
    const client = clients.find(c => c.id === clientId);
    if (client) {
      setFormData({ 
        ...formData, 
        clientId, 
        clientName: client.name,
        clientPhone: client.phone 
      });
    } else {
      setFormData({ ...formData, clientId: '', clientName: '', clientPhone: '' });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAdd(formData);
    setShowModal(false);
    setFormData({
      clientId: '',
      clientName: '',
      clientPhone: '',
      type: 'Air Ticket',
      date: new Date().toISOString().split('T')[0],
      flyingDate: '',
      from: '',
      to: '',
      amount: 0,
      cost: 0,
      status: BookingStatus.PENDING,
      description: '',
      pnr: '',
      bookingSource: ''
    });
  };

  const getClientDetails = (clientId?: string) => {
    return clients.find(c => c.id === clientId);
  };

  const filteredAndSortedBookings = useMemo(() => {
    return bookings
      .filter(booking => {
        const matchesStatus = !filters.status || booking.status === filters.status;
        const matchesClient = !filters.clientId || booking.clientId === filters.clientId;
        const matchesDate = !filters.date || booking.date === filters.date;
        return matchesStatus && matchesClient && matchesDate;
      })
      .sort((a, b) => {
        const dateA = new Date(a.date).getTime();
        const dateB = new Date(b.date).getTime();
        return filters.sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
      });
  }, [bookings, filters]);

  const clearFilters = () => {
    setFilters({
      status: '',
      clientId: '',
      date: '',
      sortOrder: 'desc'
    });
