                ${booking.from ? `<div style="font-size:11px; color:#64748b; margin-top:4px;">Sector: ${booking.from} to ${booking.to}</div>` : ''}
              </td>
              <td style="text-align: right; font-weight: 600;">৳${booking.amount.toLocaleString()}</td>
            </tr>
          </tbody>
        </table>

        <div class="financials">
          <div class="totals-table">
            <div class="total-row"><span>Subtotal</span><span>৳${booking.amount.toLocaleString()}</span></div>
            <div class="total-row grand-total"><span>Total Payable</span><span>৳${booking.amount.toLocaleString()}</span></div>
          </div>
        </div>

        <div class="footer">
