import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Ticket, 
  Receipt, 
  Users, 
  Settings, 
  Plus, 
  TrendingUp, 
  CreditCard, 
  MessageSquareText,
  Search,
  ChevronRight,
  Menu,
  X,
  Sun,
  Moon,
  BarChart3,
  DownloadCloud
} from 'lucide-react';
import { Booking, BookingStatus, Transaction, TransactionType, Client } from './types';
import Dashboard from './components/Dashboard';
import BookingList from './components/BookingList';
import TransactionList from './components/TransactionList';
import ClientList from './components/ClientList';
import AIChat from './components/AIChat';
import Forecast from './components/Forecast';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'bookings' | 'accounts' | 'ai' | 'clients' | 'forecast'>('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('darkMode');
    return saved ? JSON.parse(saved) : false;
  });

  useEffect(() => {
    localStorage.setItem('darkMode', JSON.stringify(isDarkMode));
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, [isDarkMode]);

  const handleInstallClick = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        setDeferredPrompt(null);
      }
    }
  };

  // State initialized as empty arrays
  const [clients, setClients] = useState<Client[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const stats = useMemo(() => {
    const totalIncome = transactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalExpense = transactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    const netProfit = totalIncome - totalExpense;
    const pendingCount = bookings.filter(b => b.status === BookingStatus.PENDING).length;

    return { 
      totalSales: totalIncome, 
      totalCost: totalExpense, 
      netProfit: netProfit, 
      pendingInvoices: pendingCount 
    };
  }, [transactions, bookings]);

  const addBooking = (newBooking: Omit<Booking, 'id'>) => {
    const id = Math.random().toString(36).substr(2, 9);
    setBookings(prev => [...prev, { ...newBooking, id }]);

    const transId = 't' + Math.random().toString(36).substr(2, 5);
    setTransactions(prev => [...prev, {
      id: transId,
      date: new Date().toISOString().split('T')[0],
      category: `${newBooking.type} Sale`,
      amount: newBooking.amount,
      type: TransactionType.INCOME,
      reference: `BOOKING-${id}`
    }]);
  };

  const addTransaction = (newTransaction: Omit<Transaction, 'id'>) => {
    const id = 't' + Math.random().toString(36).substr(2, 7);
    setTransactions(prev => [ { ...newTransaction, id }, ...prev ]);
  };

  const addClient = (newClient: Omit<Client, 'id' | 'createdAt'>) => {
    const id = 'c' + Math.random().toString(36).substr(2, 9);
    setClients(prev => [...prev, { ...newClient, id, createdAt: new Date().toISOString() }]);
  };

  const updateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    setBookings(prev => prev.map(b => b.clientId === updatedClient.id ? { ...b, clientName: updatedClient.name } : b));
  };

  return (
    <div className={`flex h-screen overflow-hidden font-sans transition-colors duration-300 ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'}`}>
      <aside className={`${isSidebarOpen ? 'w-64' : 'w-20'} ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} border-r transition-all duration-300 flex flex-col z-50`}>
        <div className="p-6 flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg shrink-0">
            <Ticket className="text-white w-6 h-6" />
          </div>
          {isSidebarOpen && <h1 className={`font-bold text-xl tracking-tight transition-colors ${isDarkMode ? 'text-white' : 'text-slate-800'}`}>B2C ERP</h1>}
        </div>

        <nav className="flex-1 px-4 space-y-1">
          <NavItem icon={<LayoutDashboard />} label="Dashboard" active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
          <NavItem icon={<Users />} label="Clients" active={activeTab === 'clients'} onClick={() => setActiveTab('clients')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
          <NavItem icon={<Ticket />} label="Bookings" active={activeTab === 'bookings'} onClick={() => setActiveTab('bookings')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
          <NavItem icon={<BarChart3 />} label="Forecast" active={activeTab === 'forecast'} onClick={() => setActiveTab('forecast')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
          <NavItem icon={<CreditCard />} label="Accounts" active={activeTab === 'accounts'} onClick={() => setActiveTab('accounts')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
          <NavItem icon={<MessageSquareText />} label="AI Advisor" active={activeTab === 'ai'} onClick={() => setActiveTab('ai')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
        </nav>

        <div className={`p-4 border-t ${isDarkMode ? 'border-slate-800' : 'border-slate-100'}`}>
           {deferredPrompt && (
             <button onClick={handleInstallClick} className="w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all mb-2 bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg">
              <DownloadCloud size={20} />
              {isSidebarOpen && <span className="font-bold text-sm">Install App</span>}
            </button>
           )}
           <NavItem icon={isDarkMode ? <Sun /> : <Moon />} label={isDarkMode ? "Light" : "Dark"} active={false} onClick={() => setIsDarkMode(!isDarkMode)} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        <header className={`h-16 ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} border-b flex items-center justify-between px-8 shrink-0 transition-colors`}>
          <div className="relative w-96 hidden md:block">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
            <input type="text" placeholder="Search accounts, invoices..." className={`w-full pl-10 pr-4 py-2 ${isDarkMode ? 'bg-slate-800 text-slate-100 border-slate-700' : 'bg-slate-100 text-slate-900 border-transparent'} rounded-full text-sm outline-none focus:ring-2 focus:ring-indigo-500/20`} />
          </div>
          <div className="flex items-center gap-4">
            <button onClick={() => setActiveTab('bookings')} className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-indigo-700 transition-colors text-sm font-medium">
              <Plus size={18} />
              New Booking
            </button>
            <div className={`w-10 h-10 rounded-full ${isDarkMode ? 'bg-slate-700' : 'bg-slate-200'} border-2 border-white shadow-sm overflow-hidden`}>
              <img src="https://picsum.photos/40/40" alt="Avatar" />
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 no-scrollbar">
          {activeTab === 'dashboard' && <Dashboard stats={stats} bookings={bookings} isDarkMode={isDarkMode} />}
          {activeTab === 'clients' && <ClientList clients={clients} bookings={bookings} onAdd={addClient} onUpdate={updateClient} isDarkMode={isDarkMode} />}
          {activeTab === 'bookings' && <BookingList bookings={bookings} clients={clients} onAdd={addBooking} isDarkMode={isDarkMode} />}
          {activeTab === 'forecast' && <Forecast bookings={bookings} isDarkMode={isDarkMode} />}
          {activeTab === 'accounts' && <TransactionList transactions={transactions} stats={stats} onAddTransaction={addTransaction} isDarkMode={isDarkMode} />}
          {activeTab === 'ai' && <AIChat bookings={bookings} transactions={transactions} isDarkMode={isDarkMode} />}
        </div>
      </main>
    </div>
  );
};

const NavItem = ({ icon, label, active, onClick, collapsed, isDarkMode }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all duration-200 group ${active ? isDarkMode ? 'bg-indigo-900/40 text-indigo-400' : 'bg-indigo-50 text-indigo-700' : isDarkMode ? 'text-slate-400 hover:bg-slate-800 hover:text-slate-100' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}>
    <span className={`${active ? isDarkMode ? 'text-indigo-400' : 'text-indigo-600' : isDarkMode ? 'text-slate-500 group-hover:text-slate-300' : 'text-slate-400 group-hover:text-slate-600'}`}>
      {React.cloneElement(icon, { size: 20 })}
    </span>
    {!collapsed && <span className="font-medium text-sm truncate">{label}</span>}
  </button>
);

export default App;

