import React, { useMemo } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { AgencyStats, Booking, BookingStatus } from '../types';
import { 
  DollarSign, UserCheck, Clock, TrendingUp, ArrowUpRight, 
  Ticket, Bell, PlaneTakeoff, AlertCircle, ChevronRight 
} from 'lucide-react';

interface Props {
  stats: AgencyStats;
  bookings: Booking[];
  isDarkMode?: boolean;
}

const Dashboard: React.FC<Props> = ({ stats, bookings, isDarkMode }) => {
  // Use zeroed data if no bookings exist
  const chartData = bookings.length > 0 ? [
    { name: 'Prev', sales: 0, profit: 0 },
    { name: 'Current', sales: stats.totalSales, profit: stats.netProfit },
  ] : [
    { name: 'Jan', sales: 0, profit: 0 },
    { name: 'Feb', sales: 0, profit: 0 },
    { name: 'Mar', sales: 0, profit: 0 },
    { name: 'Apr', sales: 0, profit: 0 },
    { name: 'May', sales: 0, profit: 0 },
    { name: 'Jun', sales: 0, profit: 0 },
  ];

  // Calculate upcoming flight alerts (next 7 days)
  const flightAlerts = useMemo(() => {
    const today = new Date();
    const sevenDaysLater = new Date();
    sevenDaysLater.setDate(today.getDate() + 7);

    return bookings
      .filter(b => b.type === 'Air Ticket' && b.flyingDate)
      .map(b => ({
        ...b,
        fDate: new Date(b.flyingDate!)
      }))
      .filter(b => b.fDate >= today && b.fDate <= sevenDaysLater)
      .sort((a, b) => a.fDate.getTime() - b.fDate.getTime());
  }, [bookings]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Flight Alerts Section - Only shows if there are upcoming flights */}
      {flightAlerts.length > 0 && (
        <div className={`p-5 rounded-2xl border-2 animate-pulse-slow ${isDarkMode ? 'bg-amber-950/20 border-amber-500/30' : 'bg-amber-50 border-amber-100'}`}>
          <div className="flex items-center gap-3 mb-4">
            <div className={`p-2 rounded-lg ${isDarkMode ? 'bg-amber-500/20' : 'bg-amber-500/10'}`}>
              <Bell size={20} className="text-amber-500" />
            </div>
            <h3 className={`font-bold ${isDarkMode ? 'text-amber-400' : 'text-amber-700'}`}>Urgent Flight Announcements</h3>
          </div>
          <div className="flex flex-wrap gap-4">
            {flightAlerts.map(alert => {
              const daysLeft = Math.ceil((alert.fDate.getTime() - new Date().getTime()) / (1000 * 3600 * 24));
              const isUrgent = daysLeft <= 2;

              return (
                <div key={alert.id} className={`flex-1 min-w-[280px] p-4 rounded-xl border transition-all ${
                  isUrgent 
                    ? isDarkMode ? 'bg-rose-950/40 border-rose-500/50' : 'bg-rose-50 border-rose-100'
                    : isDarkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-200'
                }`}>
                  <div className="flex justify-between items-start mb-2">
                    <div className="flex items-center gap-2">
                      <PlaneTakeoff size={16} className={isUrgent ? 'text-rose-500' : 'text-indigo-500'} />
                      <span className={`text-xs font-bold uppercase tracking-wider ${isUrgent ? 'text-rose-500' : 'text-slate-500'}`}>
                        {isUrgent ? 'Imminent Flight' : 'Upcoming'}
                      </span>
                    </div>
                    <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold ${
                      isUrgent ? 'bg-rose-500 text-white' : 'bg-slate-100 text-slate-600'
                    }`}>
                      {daysLeft === 0 ? 'Today' : `${daysLeft} Days Left`}
                    </span>
                  </div>
                  <h4 className={`font-bold text-sm ${isDarkMode ? 'text-slate-100' : 'text-slate-800'}`}>{alert.clientName}</h4>
                  <p className="text-xs text-slate-500 mt-1">{alert.from} ➔ {alert.to} | PNR: {alert.pnr || 'N/A'}</p>
                  <div className="mt-3 flex items-center justify-between">
                    <span className="text-xs font-mono text-indigo-500">{alert.flyingDate}</span>
                    <button className="text-[10px] font-bold text-indigo-600 flex items-center gap-1 hover:underline">
                      View Details <ChevronRight size={12} />
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          label="Total Revenue" 
          value={`৳${stats.totalSales.toLocaleString()}`} 
          icon={<DollarSign className="text-emerald-600" />} 
          trend="0%" 
          color={isDarkMode ? "bg-emerald-900/20" : "bg-emerald-50"}
          isDarkMode={isDarkMode}
        />
        <StatCard 
          label="Net Profit" 
          value={`৳${stats.netProfit.toLocaleString()}`} 
          icon={<TrendingUp className="text-indigo-600" />} 
          trend="0%" 
          color={isDarkMode ? "bg-indigo-900/20" : "bg-indigo-50"}
          isDarkMode={isDarkMode}
        />
        <StatCard 
          label="Active Clients" 
          value={Array.from(new Set(bookings.map(b => b.clientId))).filter(Boolean).length.toString()} 
          icon={<UserCheck className="text-amber-600" />} 
          trend="0" 
          color={isDarkMode ? "bg-amber-900/20" : "bg-amber-50"}
          isDarkMode={isDarkMode}
        />
        <StatCard 
          label="Pending Tasks" 
          value={stats.pendingInvoices.toString()} 
          icon={<Clock className="text-rose-600" />} 
          trend="0" 
          color={isDarkMode ? "bg-rose-900/20" : "bg-rose-50"}
          isDarkMode={isDarkMode}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className={`lg:col-span-2 p-6 rounded-2xl border transition-colors ${isDarkMode ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-slate-200 text-slate-900'} shadow-sm`}>
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-bold">Financial Growth</h3>
            <select className={`border rounded-lg px-3 py-1.5 text-sm outline-none transition-colors ${isDarkMode ? 'bg-slate-800 border-slate-700 text-slate-300' : 'bg-slate-50 border-slate-200 text-slate-600'}`}>
              <option>Last 6 Months</option>
            </select>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#4f46e5" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? "#1e293b" : "#f1f5f9"} />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: isDarkMode ? '#64748b' : '#94a3b8', fontSize: 12}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: isDarkMode ? '#64748b' : '#94a3b8', fontSize: 12}} />
                <Tooltip 
                  contentStyle={{
                    borderRadius: '12px', 
                    border: 'none', 
                    boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)',
                    backgroundColor: isDarkMode ? '#1e293b' : '#fff',
                    color: isDarkMode ? '#f8fafc' : '#1e293b'
                  }}
                  itemStyle={{color: isDarkMode ? '#818cf8' : '#4f46e5'}}
                />
                <Area type="monotone" dataKey="sales" stroke="#4f46e5" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className={`p-6 rounded-2xl border transition-colors ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} shadow-sm`}>
          <h3 className={`font-bold mb-6 ${isDarkMode ? 'text-white' : 'text-slate-800'}`}>Recent Bookings</h3>
          <div className="space-y-4">
            {bookings.length > 0 ? bookings.slice(0, 5).map((booking) => (
              <div key={booking.id} className={`flex items-center gap-4 p-3 rounded-xl transition-colors cursor-pointer group ${isDarkMode ? 'hover:bg-slate-800' : 'hover:bg-slate-50'}`}>
                <div className={`w-10 h-10 rounded-full flex items-center justify-center transition-colors ${isDarkMode ? 'bg-slate-800 group-hover:bg-indigo-900/40' : 'bg-slate-100 group-hover:bg-indigo-100'}`}>
                  <Ticket size={18} className={`${isDarkMode ? 'text-slate-400 group-hover:text-indigo-400' : 'text-slate-500 group-hover:text-indigo-600'}`} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className={`text-sm font-semibold truncate ${isDarkMode ? 'text-slate-200' : 'text-slate-800'}`}>{booking.clientName}</p>
                  <p className="text-xs text-slate-500 truncate">{booking.type} • {booking.date}</p>
                </div>
                <div className="text-right shrink-0">
                  <p className={`text-sm font-bold ${isDarkMode ? 'text-slate-100' : 'text-slate-800'}`}>৳{booking.amount.toLocaleString()}</p>
