                </div>
              </div>
            )) : (
              <div className="py-10 text-center text-slate-400 text-sm italic">
                No recent bookings found.
              </div>
            )}
          </div>
          <button className={`w-full mt-6 py-2.5 text-sm font-medium rounded-xl transition-colors ${
            isDarkMode ? 'bg-indigo-900/40 text-indigo-400 hover:bg-indigo-900/60' : 'bg-indigo-50 text-indigo-600 hover:bg-indigo-100'
          }`}>
            View All Reports
          </button>
        </div>
      </div>
    </div>
  );
