  ];

  // Calculate upcoming flight alerts (next 7 days)
  const flightAlerts = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const sevenDaysLater = new Date();
    sevenDaysLater.setDate(today.getDate() + 7);

    return bookings
      .filter(b => b.type === 'Air Ticket' && b.flyingDate)
      .map(b => ({
        ...b,
        fDate: new Date(b.flyingDate!)
      }))
      .filter(b => b.fDate >= today && b.fDate <= sevenDaysLater)
      .sort((a, b) => a.fDate.getTime() - b.fDate.getTime());
  }, [bookings]);

  // Today's specific statistics
  const todayFlights = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    return bookings.filter(b => b.type === 'Air Ticket' && b.flyingDate === todayStr);
  }, [bookings]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Dynamic Announcement Board */}
      {flightAlerts.length > 0 && (
        <section className={`rounded-3xl border-l-8 overflow-hidden shadow-lg transition-all ${
          isDarkMode ? 'bg-slate-900 border-indigo-500' : 'bg-white border-indigo-600'
        }`}>
          <div className={`px-6 py-4 flex items-center justify-between border-b ${isDarkMode ? 'bg-indigo-500/10 border-slate-800' : 'bg-indigo-50 border-indigo-100'}`}>
            <div className="flex items-center gap-3">
              <div className="relative">
                <Bell size={20} className="text-indigo-600 animate-bounce" />
                <span className="absolute -top-1 -right-1 w-2 h-2 bg-rose-500 rounded-full"></span>
              </div>
              <h3 className={`font-bold text-sm md:text-base ${isDarkMode ? 'text-indigo-400' : 'text-indigo-900'}`}>
                Operational Announcements & Flight Alerts
              </h3>
            </div>
            <span className={`text-[10px] md:text-xs font-bold px-3 py-1 rounded-full ${isDarkMode ? 'bg-indigo-900/40 text-indigo-300' : 'bg-indigo-100 text-indigo-700'}`}>
              {flightAlerts.length} Upcoming Flights
            </span>
          </div>

          <div className="p-2 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2">
            {flightAlerts.map(alert => {
              const diffTime = alert.fDate.getTime() - new Date().setHours(0,0,0,0);
              const daysLeft = Math.ceil(diffTime / (1000 * 3600 * 24));
              const isUrgent = daysLeft <= 1;
              const profit = alert.amount - alert.cost;

              return (
                <div key={alert.id} className={`p-4 rounded-2xl border transition-all hover:scale-[1.02] cursor-pointer ${
                  isUrgent 
                    ? isDarkMode ? 'bg-rose-950/20 border-rose-500/40' : 'bg-rose-50 border-rose-200'
                    : isDarkMode ? 'bg-slate-800/40 border-slate-700' : 'bg-slate-50/50 border-slate-100'
                }`}>
                  <div className="flex justify-between items-start mb-2">
                    <div className="flex items-center gap-2">
                      {isUrgent ? (
                        <Zap size={14} className="text-rose-500 fill-rose-500" />
                      ) : (
                        <PlaneTakeoff size={14} className="text-indigo-500" />
                      )}
                      <span className={`text-[10px] font-black uppercase tracking-widest ${isUrgent ? 'text-rose-600' : 'text-slate-400'}`}>
                        {isUrgent ? 'IMMEDIATE DEP.' : 'SCHEDULED'}
                      </span>
                    </div>
                    <div className="text-right">
                      <div className={`text-[10px] font-bold ${isUrgent ? 'text-rose-600' : 'text-indigo-600'}`}>
                        Profit: ৳{profit.toLocaleString()}
                      </div>
                    </div>
                  </div>

                  <h4 className={`font-bold text-sm truncate ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
                    {alert.clientName}
                  </h4>
                  <div className="flex items-center gap-1.5 mt-1">
                    <span className="text-xs font-mono text-slate-500">{alert.from}</span>
                    <ChevronRight size={10} className="text-slate-300" />
                    <span className="text-xs font-mono text-slate-500">{alert.to}</span>
                    <span className="text-[10px] px-1.5 py-0.5 bg-slate-200 dark:bg-slate-700 rounded text-slate-500 dark:text-slate-400 ml-auto">
                      {alert.pnr || 'NO-PNR'}
                    </span>
                  </div>

                  <div className="mt-4 flex items-center justify-between border-t border-slate-200/50 dark:border-slate-700/50 pt-2">
                    <div className="flex items-center gap-1">
                      <CalendarDays size={12} className="text-slate-400" />
                      <span className={`text-xs font-bold ${isUrgent ? 'text-rose-600' : 'text-slate-600'}`}>
                        {alert.flyingDate}
                      </span>
                    </div>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-md ${
                      isUrgent ? 'bg-rose-600 text-white' : 'bg-indigo-600 text-white'
                    }`}>
                      {daysLeft === 0 ? 'Today' : daysLeft === 1 ? 'Tomorrow' : `${daysLeft}d left`}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        </section>
      )}

      {/* Main KPI Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          label="Total Revenue" 
          value={`৳${stats.totalSales.toLocaleString()}`} 
          icon={<DollarSign className="text-emerald-600" />} 
          trend="0%" 
          color={isDarkMode ? "bg-emerald-900/20" : "bg-emerald-50"}
          isDarkMode={isDarkMode}
        />
        <StatCard 
          label="Net Profit" 
          value={`৳${stats.netProfit.toLocaleString()}`} 
          icon={<TrendingUp className="text-indigo-600" />} 
          trend="0%" 
          color={isDarkMode ? "bg-indigo-900/20" : "bg-indigo-50"}
          isDarkMode={isDarkMode}
        />
        <StatCard 
          label="Today's Flights" 
          value={todayFlights.length.toString()} 
          icon={<PlaneTakeoff className="text-amber-600" />} 
          trend="Live" 
          color={isDarkMode ? "bg-amber-900/20" : "bg-amber-50"}
          isDarkMode={isDarkMode}
        />
        <StatCard 
          label="Pending Tasks" 
          value={stats.pendingInvoices.toString()} 
          icon={<Clock className="text-rose-600" />} 
          trend="Alert" 
          color={isDarkMode ? "bg-rose-900/20" : "bg-rose-50"}
          isDarkMode={isDarkMode}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className={`lg:col-span-2 p-6 rounded-3xl border transition-colors ${isDarkMode ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-slate-200 text-slate-900'} shadow-sm`}>
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-bold">Agency Financial Pulse</h3>
            <div className={`px-3 py-1 rounded-full text-xs font-bold ${isDarkMode ? 'bg-slate-800 text-slate-400' : 'bg-slate-50 text-slate-500'}`}>
              Real-time Analytics
            </div>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#4f46e5" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#4f46e5" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? "#1e293b" : "#f1f5f9"} />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: isDarkMode ? '#64748b' : '#94a3b8', fontSize: 12}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: isDarkMode ? '#64748b' : '#94a3b8', fontSize: 12}} />
                <Tooltip 
                  contentStyle={{
                    borderRadius: '12px', 
                    border: 'none', 
                    boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)',
                    backgroundColor: isDarkMode ? '#1e293b' : '#fff',
                    color: isDarkMode ? '#f8fafc' : '#1e293b'
                  }}
                  itemStyle={{color: '#4f46e5'}}
                />
                <Area type="monotone" dataKey="sales" stroke="#4f46e5" strokeWidth={3} fillOpacity={1} fill="url(#colorSales)" />
                <Area type="monotone" dataKey="profit" stroke="#10b981" strokeWidth={3} fillOpacity={0} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className={`p-6 rounded-3xl border transition-colors ${isDarkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'} shadow-sm`}>
          <h3 className={`font-bold mb-6 ${isDarkMode ? 'text-white' : 'text-slate-800'}`}>Service Log</h3>
          <div className="space-y-4">
            {bookings.length > 0 ? bookings.slice(0, 6).map((booking) => (
              <div key={booking.id} className={`flex items-center gap-4 p-3 rounded-2xl transition-colors cursor-pointer group ${isDarkMode ? 'hover:bg-slate-800' : 'hover:bg-slate-50'}`}>
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-colors ${isDarkMode ? 'bg-slate-800 group-hover:bg-indigo-900/40' : 'bg-slate-100 group-hover:bg-indigo-100'}`}>
                  <Ticket size={18} className={`${isDarkMode ? 'text-slate-400 group-hover:text-indigo-400' : 'text-slate-500 group-hover:text-indigo-600'}`} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className={`text-sm font-semibold truncate ${isDarkMode ? 'text-slate-200' : 'text-slate-800'}`}>{booking.clientName}</p>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{booking.type} • {booking.date}</p>
                </div>
                <div className="text-right shrink-0">
                  <p className={`text-sm font-bold ${isDarkMode ? 'text-slate-100' : 'text-slate-800'}`}>৳{booking.amount.toLocaleString()}</p>
                  <StatusBadge status={booking.status} isDarkMode={isDarkMode} />
                </div>
              </div>
            )) : (
              <div className="py-12 text-center">
                <ShieldAlert className="mx-auto text-slate-300 mb-2" size={32} />
                <p className="text-slate-400 text-sm italic">No recent activities.</p>
              </div>
            )}
          </div>
          <button className={`w-full mt-6 py-3 text-sm font-bold rounded-2xl transition-all ${
            isDarkMode ? 'bg-indigo-900/40 text-indigo-400 hover:bg-indigo-900/60' : 'bg-indigo-50 text-indigo-600 hover:bg-indigo-100'
          }`}>
            Download Detailed Report
          </button>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ label, value, icon, trend, color, isDarkMode }: any) => (
  <div className={`p-6 rounded-3xl border transition-all ${isDarkMode ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-slate-200 text-slate-900'} shadow-sm hover:shadow-md group`}>
    <div className="flex items-start justify-between mb-4">
      <div className={`p-3 rounded-2xl transition-colors group-hover:scale-110 duration-300 ${color}`}>
        {icon}
      </div>
      <div className={`flex items-center gap-1 px-2 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter ${
        trend.includes('%') ? 'text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20' : 'text-indigo-600 bg-indigo-50 dark:bg-indigo-900/20'
      }`}>
        {trend === 'Live' ? <Zap size={10} className="animate-pulse" /> : <ArrowUpRight size={10} />}
        {trend}
      </div>
    </div>
    <p className={`${isDarkMode ? 'text-slate-400' : 'text-slate-500'} text-xs font-bold uppercase tracking-widest mb-1`}>{label}</p>
    <h4 className="text-2xl font-black">{value}</h4>
  </div>
);

const StatusBadge = ({ status, isDarkMode }: { status: BookingStatus, isDarkMode?: boolean }) => {
  const styles = {
    [BookingStatus.CONFIRMED]: isDarkMode ? 'bg-emerald-900/30 text-emerald-400' : 'bg-emerald-50 text-emerald-600',
    [BookingStatus.PENDING]: isDarkMode ? 'bg-amber-900/30 text-amber-400' : 'bg-amber-50 text-amber-600',
    [BookingStatus.CANCELLED]: isDarkMode ? 'bg-rose-900/30 text-rose-400' : 'bg-rose-50 text-rose-600',
  };
  return (
    <span className={`text-[10px] px-2 py-0.5 rounded-md font-black uppercase tracking-tighter ${styles[status]}`}>
      {status}
    </span>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Ticket, 
  Receipt, 
  Users, 
  Settings, 
  Plus, 
  TrendingUp, 
  CreditCard, 
  MessageSquareText,
  Search,
  ChevronRight,
  Menu,
  X,
  Sun,
  Moon,
  BarChart3,
  DownloadCloud,
  Plane
} from 'lucide-react';
import { Booking, BookingStatus, Transaction, TransactionType, Client } from './types';
import Dashboard from './components/Dashboard';
import BookingList from './components/BookingList';
import TransactionList from './components/TransactionList';
import ClientList from './components/ClientList';
import AIChat from './components/AIChat';
import Forecast from './components/Forecast';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'bookings' | 'accounts' | 'ai' | 'clients' | 'forecast'>('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('darkMode');
    return saved ? JSON.parse(saved) : false;
  });

  useEffect(() => {
    localStorage.setItem('darkMode', JSON.stringify(isDarkMode));
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      document.body.style.backgroundColor = '#020617';
    } else {
      document.documentElement.classList.remove('dark');
      document.body.style.backgroundColor = '#f8faff';
    }

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
  }, [isDarkMode]);

  const handleInstallClick = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        setDeferredPrompt(null);
      }
    }
  };

  const [clients, setClients] = useState<Client[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const stats = useMemo(() => {
    const totalIncome = transactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalExpense = transactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    const netProfit = totalIncome - totalExpense;
    const pendingCount = bookings.filter(b => b.status === BookingStatus.PENDING).length;

    return { 
      totalSales: totalIncome, 
      totalCost: totalExpense, 
      netProfit: netProfit, 
      pendingInvoices: pendingCount 
    };
  }, [transactions, bookings]);

  const addBooking = (newBooking: Omit<Booking, 'id'>) => {
    const id = Math.random().toString(36).substr(2, 9);
    setBookings(prev => [...prev, { ...newBooking, id }]);

    const transId = 't' + Math.random().toString(36).substr(2, 5);
    setTransactions(prev => [...prev, {
      id: transId,
      date: new Date().toISOString().split('T')[0],
      category: `${newBooking.type} Sale`,
      amount: newBooking.amount,
      type: TransactionType.INCOME,
      reference: `BOOKING-${id}`
    }]);
  };

  const addTransaction = (newTransaction: Omit<Transaction, 'id'>) => {
    const id = 't' + Math.random().toString(36).substr(2, 7);
    setTransactions(prev => [ { ...newTransaction, id }, ...prev ]);
  };

  const addClient = (newClient: Omit<Client, 'id' | 'createdAt'>) => {
    const id = 'c' + Math.random().toString(36).substr(2, 9);
    setClients(prev => [...prev, { ...newClient, id, createdAt: new Date().toISOString() }]);
  };

  const updateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    setBookings(prev => prev.map(b => b.clientId === updatedClient.id ? { ...b, clientName: updatedClient.name } : b));
  };

  return (
    <div className={`flex h-screen overflow-hidden font-sans transition-all duration-500 ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-[#f8faff] text-slate-900'}`}>

      {/* Unique Sidebar with Gradient & Blur */}
      <aside className={`${isSidebarOpen ? 'w-72' : 'w-24'} ${isDarkMode ? 'bg-slate-900/40 border-slate-800' : 'bg-white border-slate-100'} border-r transition-all duration-500 flex flex-col z-50 relative group`}>
        <div className="p-8 flex items-center gap-4">
          <div className="vibrant-gradient p-2.5 rounded-2xl vibrant-glow shrink-0">
            <Plane className="text-white w-6 h-6 rotate-45" />
          </div>
          {isSidebarOpen && (
            <div className="animate-in fade-in slide-in-from-left-2 duration-300">
              <h1 className={`font-black text-lg tracking-tighter transition-colors ${isDarkMode ? 'text-white' : 'text-slate-800'}`}>
                B2C <span className="text-violet-600">TRAVEL</span>
              </h1>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest -mt-1">ERP Systems</p>
            </div>
          )}
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          <NavItem icon={<LayoutDashboard />} label="Dashboard" active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
          <NavItem icon={<Users />} label="Client Base" active={activeTab === 'clients'} onClick={() => setActiveTab('clients')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
          <NavItem icon={<Ticket />} label="Active Bookings" active={activeTab === 'bookings'} onClick={() => setActiveTab('bookings')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
          <NavItem icon={<BarChart3 />} label="AI Forecast" active={activeTab === 'forecast'} onClick={() => setActiveTab('forecast')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
          <NavItem icon={<CreditCard />} label="Financials" active={activeTab === 'accounts'} onClick={() => setActiveTab('accounts')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
          <NavItem icon={<MessageSquareText />} label="Gemini AI" active={activeTab === 'ai'} onClick={() => setActiveTab('ai')} collapsed={!isSidebarOpen} isDarkMode={isDarkMode} />
        </nav>

        <div className={`p-6 border-t ${isDarkMode ? 'border-slate-800' : 'border-slate-50'}`}>
           {deferredPrompt && (
             <button onClick={handleInstallClick} className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all mb-4 bg-indigo-600 text-white hover:vibrant-gradient shadow-lg">
              <DownloadCloud size={20} />
              {isSidebarOpen && <span className="font-bold text-sm">Install App</span>}
            </button>
           )}
           <div className={`flex items-center gap-3 px-4 py-3 rounded-2xl ${isDarkMode ? 'bg-slate-800/50' : 'bg-slate-50'}`}>
             <button onClick={() => setIsDarkMode(!isDarkMode)} className={`p-2 rounded-xl transition-all ${isDarkMode ? 'bg-amber-500/20 text-amber-500' : 'bg-violet-600 text-white shadow-md'}`}>
               {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
             </button>
             {isSidebarOpen && <span className="text-xs font-bold uppercase tracking-widest text-slate-400">{isDarkMode ? 'Light Mode' : 'Dark Mode'}</span>}
           </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {/* Subtle Background Accent */}
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-violet-600/5 blur-[120px] rounded-full pointer-events-none"></div>

        <header className={`h-20 ${isDarkMode ? 'bg-slate-950/50 border-slate-800' : 'bg-white/80 border-slate-100'} backdrop-blur-md border-b flex items-center justify-between px-10 shrink-0 z-40 transition-colors`}>
          <div className="flex items-center gap-4">
             <button onClick={() => setSidebarOpen(!isSidebarOpen)} className={`p-2 rounded-xl transition-colors ${isDarkMode ? 'text-slate-400 hover:bg-slate-800' : 'text-slate-500 hover:bg-slate-50'}`}>
               <Menu size={22} />
             </button>
             <div className="relative w-80 hidden md:block">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
              <input type="text" placeholder="Search itinerary, PNR..." className={`w-full pl-12 pr-4 py-2.5 ${isDarkMode ? 'bg-slate-900 text-slate-100 border-slate-800' : 'bg-slate-100/50 text-slate-900 border-transparent'} rounded-2xl text-xs font-medium outline-none focus:ring-2 focus:ring-violet-500/20 transition-all`} />
            </div>
          </div>

          <div className="flex items-center gap-6">
            <button onClick={() => setActiveTab('bookings')} className="vibrant-gradient text-white px-6 py-2.5 rounded-2xl flex items-center gap-2 hover:scale-[1.02] active:scale-95 transition-all text-xs font-bold shadow-lg shadow-violet-500/20">
              <Plus size={18} />
              NEW RESERVATION
            </button>
            <div className="h-10 w-[1px] bg-slate-200 dark:bg-slate-800 hidden md:block"></div>
            <div className="flex items-center gap-3">
              <div className="text-right hidden sm:block">
                <p className={`text-xs font-black ${isDarkMode ? 'text-white' : 'text-slate-800'}`}>Admin Panel</p>
                <p className="text-[10px] text-violet-500 font-bold uppercase tracking-widest">B2C Ticket</p>
              </div>
              <div className="w-11 h-11 rounded-2xl vibrant-gradient p-[2px] shadow-lg">
                <div className={`w-full h-full rounded-[14px] overflow-hidden border-2 ${isDarkMode ? 'border-slate-900' : 'border-white'}`}>
                  <img src="https://picsum.photos/80/80?random=1" alt="Avatar" className="w-full h-full object-cover" />
                </div>
              </div>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 md:p-10 no-scrollbar z-10">
          <div className="max-w-7xl mx-auto">
            {activeTab === 'dashboard' && <Dashboard stats={stats} bookings={bookings} isDarkMode={isDarkMode} />}
            {activeTab === 'clients' && <ClientList clients={clients} bookings={bookings} onAdd={addClient} onUpdate={updateClient} isDarkMode={isDarkMode} />}
            {activeTab === 'bookings' && <BookingList bookings={bookings} clients={clients} onAdd={addBooking} isDarkMode={isDarkMode} />}
            {activeTab === 'forecast' && <Forecast bookings={bookings} isDarkMode={isDarkMode} />}
            {activeTab === 'accounts' && <TransactionList transactions={transactions} stats={stats} onAddTransaction={addTransaction} isDarkMode={isDarkMode} />}
            {activeTab === 'ai' && <AIChat bookings={bookings} transactions={transactions} isDarkMode={isDarkMode} />}
          </div>
        </div>
      </main>
    </div>
  );
};

const NavItem = ({ icon, label, active, onClick, collapsed, isDarkMode }: any) => (
