      {!selectedClientId ? (
        <div className={`p-24 text-center rounded-[48px] border-2 border-dashed animate-in fade-in duration-700 ${isDarkMode ? 'bg-slate-900/40 border-slate-800' : 'bg-slate-50 border-slate-200'}`}>
          <div className="relative inline-block mb-6">
            <div className="absolute inset-0 bg-violet-500 blur-2xl opacity-20 animate-pulse"></div>
            <History className="text-violet-500 relative z-10" size={80} />
          </div>
          <h3 className={`text-xl font-black uppercase tracking-widest ${isDarkMode ? 'text-slate-300' : 'text-slate-800'}`}>Initialize Ledger Inquiry</h3>
          <p className="text-xs text-slate-500 mt-2 font-medium max-w-sm mx-auto">Please select a passenger from the terminal menu above to generate their date-wise financial statement.</p>
        </div>
      ) : (
        <>
          {/* Summary Dashboard for the Selected Period */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 animate-in slide-in-from-bottom-4 duration-500">
            <StatCard 
              label="Opening Bal" 
              value={`৳${openingBalance.toLocaleString()}`} 
              icon={<History className="text-slate-400" />} 
              isDarkMode={isDarkMode} 
            />
            <StatCard 
              label="Period Billed" 
              value={`৳${periodTotals.debit.toLocaleString()}`} 
              icon={<ArrowUpRight className="text-rose-500" />} 
              isDarkMode={isDarkMode} 
            />
            <StatCard 
              label="Period Paid" 
              value={`৳${periodTotals.credit.toLocaleString()}`} 
              icon={<ArrowDownRight className="text-emerald-500" />} 
              isDarkMode={isDarkMode} 
            />
            <StatCard 
              label="Closing Bal" 
              value={`৳${(openingBalance + periodTotals.debit - periodTotals.credit).toLocaleString()}`} 
              icon={<Wallet className="text-violet-500" />} 
              isDarkMode={isDarkMode}
              highlight
            />
          </div>

          <div className={`rounded-[40px] border-2 overflow-hidden shadow-2xl transition-all ${
            isDarkMode ? 'bg-[#0f172a] border-slate-800' : 'bg-white border-slate-50 shadow-xl shadow-slate-200/50'
          }`}>
            <div className="overflow-x-auto no-scrollbar">
              <table className="w-full text-left">
                <thead>
                  <tr className={`border-b-2 ${isDarkMode ? 'bg-slate-900/50 border-slate-800' : 'bg-slate-50/50 border-slate-100'}`}>
                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Transaction Date</th>
                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">Description / Ledger Ref</th>
                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Debit (+)</th>
                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Credit (-)</th>
                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Balance B/F</th>
                  </tr>
                </thead>
                <tbody className={`divide-y-2 ${isDarkMode ? 'divide-slate-800/50' : 'divide-slate-50'}`}>
                  {/* Opening Balance Row */}
                  <tr className={`${isDarkMode ? 'bg-violet-900/5' : 'bg-violet-50/30'} italic`}>
                    <td className="px-8 py-6">
                      <span className="text-[10px] font-black text-violet-500 uppercase tracking-widest">{startDate}</span>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-2">
                        <div className="w-2 h-2 rounded-full bg-violet-500"></div>
                        <p className={`text-xs font-black uppercase tracking-tight ${isDarkMode ? 'text-slate-300' : 'text-slate-600'}`}>Opening Balance Carried Forward</p>
                      </div>
                    </td>
                    <td className="px-8 py-6 text-right text-slate-300">--</td>
                    <td className="px-8 py-6 text-right text-slate-300">--</td>
                    <td className="px-8 py-6 text-right">
                      <span className={`text-sm font-black tracking-tighter ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>৳{openingBalance.toLocaleString()}</span>
                    </td>
                  </tr>

                  {filteredData.map((row, idx) => (
                    <tr key={idx} className={`group transition-all ${isDarkMode ? 'hover:bg-violet-600/5' : 'hover:bg-violet-50/50'}`}>
                      <td className="px-8 py-6">
                        <span className={`text-[10px] font-black uppercase ${isDarkMode ? 'text-slate-500' : 'text-slate-400'}`}>{row.date}</span>
                      </td>
                      <td className="px-8 py-6">
                        <div>
                          <p className={`text-sm font-black truncate tracking-tight transition-colors ${isDarkMode ? 'text-slate-100 group-hover:text-violet-400' : 'text-slate-800 group-hover:text-violet-700'}`}>{row.description}</p>
                          {row.pax && (
                            <div className="flex items-center gap-1.5 mt-0.5 px-2 py-0.5 rounded-md bg-indigo-500/10 text-indigo-500 w-fit">
                               <Users size={10} />
                               <span className="text-[9px] font-black uppercase tracking-widest">{row.pax} Pax</span>
                            </div>
                          )}
                          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-0.5">{row.ref}</p>
                        </div>
                      </td>
                      <td className="px-8 py-6 text-right">
                        {row.debit > 0 && <span className="text-sm font-black text-rose-500">৳{row.debit.toLocaleString()}</span>}
                      </td>
                      <td className="px-8 py-6 text-right">
                        {row.credit > 0 && <span className="text-sm font-black text-emerald-500">৳{row.credit.toLocaleString()}</span>}
                      </td>
                      <td className="px-8 py-6 text-right">
                        <span className={`text-sm font-black tracking-tighter ${isDarkMode ? 'text-violet-400' : 'text-violet-700'}`}>৳{row.balance.toLocaleString()}</span>
                      </td>
                    </tr>
                  ))}

                  {filteredData.length === 0 && (
                    <tr>
                      <td colSpan={5} className="px-8 py-12 text-center">
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest italic">No transactions recorded for this specific period.</p>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>

            {/* Detailed Summary Footer */}
            <div className={`p-10 border-t-2 ${isDarkMode ? 'bg-slate-900/50 border-slate-800' : 'bg-slate-50/50 border-slate-100'} flex flex-col md:flex-row justify-between items-center gap-8`}>
              <div className="flex items-center gap-4">
                 <div className="p-4 rounded-2xl bg-violet-600/10 border border-violet-500/20 text-violet-500">
                    <Filter size={24} />
                 </div>
                 <div>
                    <p className="text-xs font-black uppercase tracking-widest text-slate-400">Reporting Range</p>
                    <p className={`text-sm font-black ${isDarkMode ? 'text-slate-200' : 'text-slate-800'}`}>{startDate} <span className="text-violet-500 mx-2">➔</span> {endDate}</p>
                 </div>
              </div>

              <div className="w-full max-w-sm space-y-3 bg-white/50 dark:bg-black/20 p-6 rounded-3xl border border-slate-100 dark:border-slate-800">
                <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest text-slate-400">
                  <span>Opening Balance</span>
                  <span className="text-slate-600 dark:text-slate-300">৳{openingBalance.toLocaleString()}</span>
                </div>
                <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest text-slate-400">
                  <span>Period Changes</span>
                  <span className={periodTotals.debit >= periodTotals.credit ? 'text-rose-500' : 'text-emerald-500'}>
                    {periodTotals.debit >= periodTotals.credit ? '+' : ''}৳{(periodTotals.debit - periodTotals.credit).toLocaleString()}
                  </span>
                </div>
                <div className="pt-3 border-t-2 border-slate-200 dark:border-slate-800 flex justify-between items-center">
                  <span className="text-xs font-black uppercase tracking-tight text-slate-800 dark:text-white">Closing Balance</span>
                  <span className={`text-2xl font-black tracking-tighter ${ (openingBalance + periodTotals.debit - periodTotals.credit) > 0 ? 'text-rose-500' : 'text-emerald-500'}`}>
                    ৳{(openingBalance + periodTotals.debit - periodTotals.credit).toLocaleString()}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

const StatCard = ({ label, value, icon, isDarkMode, highlight }: any) => (
  <div className={`p-6 rounded-[32px] border-2 transition-all group hover:scale-[1.02] ${
    isDarkMode 
      ? highlight ? 'bg-violet-900/10 border-violet-500/30' : 'bg-slate-900 border-slate-800' 
      : highlight ? 'bg-violet-50 border-violet-100 shadow-xl shadow-violet-200/20' : 'bg-white border-slate-100 shadow-lg shadow-slate-200/40'
  }`}>
    <div className="flex items-center gap-4">
      <div className={`p-3.5 rounded-2xl transition-transform group-hover:rotate-6 ${isDarkMode ? 'bg-slate-800' : 'bg-slate-50'}`}>
        {icon}
      </div>
      <div>
        <p className="text-[9px] font-black uppercase tracking-widest text-slate-400 mb-0.5">{label}</p>
        <p className={`text-lg font-black tracking-tighter transition-colors ${isDarkMode ? highlight ? 'text-violet-400' : 'text-white' : highlight ? 'text-violet-700' : 'text-slate-900'}`}>{value}</p>
      </div>
    </div>
  </div>
);

export default StatementView;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Ticket, 
  Receipt, 
  Users, 
  Settings, 
  Plus, 
  TrendingUp, 
  CreditCard, 
  MessageSquareText,
  Search,
  ChevronRight,
  Menu,
  X,
  Sun,
  Moon,
  BarChart3,
  DownloadCloud,
  Plane,
  FileText,
  History,
  Bell
} from 'lucide-react';
import { Booking, BookingStatus, Transaction, TransactionType, Client } from './types';
import Dashboard from './components/Dashboard';
import BookingList from './components/BookingList';
import TransactionList from './components/TransactionList';
import ClientList from './components/ClientList';
import AIChat from './components/AIChat';
import Forecast from './components/Forecast';
import InvoiceList from './components/InvoiceList';
import StatementView from './components/StatementView';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'bookings' | 'accounts' | 'ai' | 'clients' | 'forecast' | 'invoices' | 'statements'>('dashboard');
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(window.innerWidth > 1024);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('darkMode');
    return saved ? JSON.parse(saved) : false;
  });

  useEffect(() => {
    localStorage.setItem('darkMode', JSON.stringify(isDarkMode));
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      document.body.style.backgroundColor = '#020617';
    } else {
      document.documentElement.classList.remove('dark');
      document.body.style.backgroundColor = '#f0f4ff';
    }

    const handleResize = () => {
      if (window.innerWidth <= 1024) setSidebarOpen(false);
      else setSidebarOpen(true);
    };

    window.addEventListener('resize', handleResize);
    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });
    return () => window.removeEventListener('resize', handleResize);
  }, [isDarkMode]);

  const handleInstallClick = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        setDeferredPrompt(null);
      }
    }
  };

  const [clients, setClients] = useState<Client[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const stats = useMemo(() => {
    const totalIncome = transactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalExpense = transactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    const netProfit = totalIncome - totalExpense;
    const pendingCount = bookings.filter(b => b.status === BookingStatus.PENDING).length;

    return { 
      totalSales: totalIncome, 
      totalCost: totalExpense, 
      netProfit: netProfit, 
      pendingInvoices: pendingCount 
    };
  }, [transactions, bookings]);

  const addBooking = (newBooking: Omit<Booking, 'id'>) => {
    const id = Math.random().toString(36).substr(2, 9);
    setBookings(prev => [...prev, { ...newBooking, id }]);

    const transId = 't' + Math.random().toString(36).substr(2, 5);
    setTransactions(prev => [...prev, {
      id: transId,
      date: new Date().toISOString().split('T')[0],
      category: `${newBooking.type} Sale`,
      amount: newBooking.amount,
      type: TransactionType.INCOME,
      bookingId: id,
      reference: `BOOKING-${id}`
    }]);
  };

  const addTransaction = (newTransaction: Omit<Transaction, 'id'>) => {
    const id = 't' + Math.random().toString(36).substr(2, 7);
    setTransactions(prev => [ { ...newTransaction, id }, ...prev ]);
  };

  const addClient = (newClient: Omit<Client, 'id' | 'createdAt'>) => {
    const id = 'c' + Math.random().toString(36).substr(2, 9);
    setClients(prev => [...prev, { ...newClient, id, createdAt: new Date().toISOString() }]);
  };

  const updateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
  };

  const navigateToStatement = (clientId: string) => {
    setSelectedClientId(clientId);
    setActiveTab('statements');
    if (window.innerWidth <= 1024) setSidebarOpen(false);
  };

  const menuItems = [
    { id: 'dashboard', label: 'Overview', icon: <LayoutDashboard /> },
    { id: 'clients', label: 'Customers', icon: <Users /> },
    { id: 'bookings', label: 'Bookings', icon: <Ticket /> },
    { id: 'invoices', label: 'Billing', icon: <FileText /> },
    { id: 'statements', label: 'Ledgers', icon: <History /> },
    { id: 'forecast', label: 'AI Trends', icon: <BarChart3 /> },
    { id: 'accounts', label: 'Finance', icon: <CreditCard /> },
    { id: 'ai', label: 'Ask Gemini', icon: <MessageSquareText /> },
  ];

  return (
    <div className={`flex h-screen overflow-hidden font-sans transition-all duration-500 ${isDarkMode ? 'bg-[#020617] text-slate-100' : 'bg-[#f0f4ff] text-slate-900'}`}>

      {/* Sidebar - Mobile Responsive */}
      <div 
        className={`fixed inset-0 bg-black/60 z-[60] lg:hidden transition-opacity duration-300 ${isSidebarOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
        onClick={() => setSidebarOpen(false)}
      />

      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] transition-all duration-500 transform ${isSidebarOpen ? 'translate-x-0 w-72' : '-translate-x-full lg:translate-x-0 lg:w-20'} ${isDarkMode ? 'bg-slate-900/90 border-slate-800' : 'bg-white/90 border-slate-100'} glass-panel border-r flex flex-col`}>
        <div className="p-6 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="vibrant-gradient p-2.5 rounded-2xl shadow-lg shadow-indigo-500/30">
              <Plane className="text-white w-5 h-5 rotate-45" />
            </div>
            {isSidebarOpen && (
              <div className="animate-in fade-in slide-in-from-left-2 duration-300">
                <h1 className="font-black text-lg tracking-tighter">B2C <span className="text-indigo-600">TRAVEL</span></h1>
              </div>
            )}
          </div>
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2 rounded-xl bg-slate-100 dark:bg-slate-800">
            <X size={20} />
          </button>
        </div>

        <nav className="flex-1 px-4 space-y-1.5 mt-4 overflow-y-auto no-scrollbar">
          {menuItems.map(item => (
            <button 
              key={item.id}
              onClick={() => {
                setActiveTab(item.id as any);
                if (window.innerWidth <= 1024) setSidebarOpen(false);
              }} 
              className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl transition-all duration-300 group relative ${
                activeTab === item.id 
                  ? 'vibrant-gradient text-white shadow-xl shadow-indigo-500/20' 
                  : isDarkMode ? 'text-slate-500 hover:bg-slate-800/50 hover:text-slate-200' : 'text-slate-500 hover:bg-indigo-50 hover:text-indigo-700'
              }`}
            >
              <span className={`${activeTab === item.id ? 'text-white' : 'text-slate-400 group-hover:text-indigo-600'} transition-colors`}>
                {React.cloneElement(item.icon as any, { size: 20 })}
              </span>
              {isSidebarOpen && <span className="font-bold text-xs uppercase tracking-widest">{item.label}</span>}
              {activeTab === item.id && !isSidebarOpen && <div className="absolute right-0 w-1.5 h-6 bg-white rounded-l-full"></div>}
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100 dark:border-slate-800">
           <div className={`flex items-center gap-3 p-3 rounded-2xl ${isDarkMode ? 'bg-slate-800/40' : 'bg-slate-50'}`}>
             <button onClick={() => setIsDarkMode(!isDarkMode)} className={`p-2 rounded-xl transition-all ${isDarkMode ? 'bg-amber-500/20 text-amber-500' : 'bg-indigo-600 text-white shadow-md'}`}>
               {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
             </button>
             {isSidebarOpen && <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{isDarkMode ? 'Day Shift' : 'Night Shift'}</span>}
           </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className={`h-20 ${isDarkMode ? 'bg-slate-950/80 border-slate-800' : 'bg-white/80 border-slate-100'} glass-panel border-b flex items-center justify-between px-6 md:px-10 shrink-0 z-40 transition-colors`}>
          <div className="flex items-center gap-4">
             <button onClick={() => setSidebarOpen(true)} className={`lg:hidden p-2 rounded-xl transition-colors ${isDarkMode ? 'text-slate-400 bg-slate-900' : 'text-slate-500 bg-white shadow-sm'}`}>
               <Menu size={22} />
             </button>
             <div className="relative w-48 md:w-80 hidden sm:block">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
              <input type="text" placeholder="Search terminal..." className={`w-full pl-12 pr-4 py-2.5 ${isDarkMode ? 'bg-slate-900 text-slate-100 border-slate-800' : 'bg-slate-100/50 text-slate-900 border-transparent shadow-inner'} rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500/20 transition-all`} />
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => setActiveTab('bookings')} 
              className="cyan-gradient text-white p-2.5 sm:px-6 sm:py-2.5 rounded-2xl flex items-center gap-2 hover:scale-[1.02] active:scale-95 transition-all text-xs font-black shadow-lg shadow-cyan-500/20"
            >
              <Plus size={18} />
              <span className="hidden sm:inline">NEW TICKET</span>
            </button>
            <button className={`p-2.5 rounded-2xl relative transition-all ${isDarkMode ? 'bg-slate-900 text-slate-400' : 'bg-white text-slate-500 shadow-sm'}`}>
              <Bell size={18} />
              <span className="absolute top-2 right-2 w-2 h-2 bg-rose-500 rounded-full border-2 border-white dark:border-slate-900"></span>
            </button>
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 md:w-11 md:h-11 rounded-2xl vibrant-gradient p-[2px] shadow-lg">
                <div className={`w-full h-full rounded-[14px] overflow-hidden border-2 ${isDarkMode ? 'border-slate-900' : 'border-white'}`}>
                  <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Felix" alt="Avatar" className="w-full h-full object-cover" />
                </div>
              </div>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 no-scrollbar z-10">
          <div className="max-w-7xl mx-auto space-y-6">
            {activeTab === 'dashboard' && <Dashboard stats={stats} bookings={bookings} isDarkMode={isDarkMode} />}
            {activeTab === 'clients' && <ClientList clients={clients} bookings={bookings} onAdd={addClient} onUpdate={updateClient} onNavigateToStatement={navigateToStatement} isDarkMode={isDarkMode} />}
            {activeTab === 'bookings' && <BookingList bookings={bookings} clients={clients} onAdd={addBooking} isDarkMode={isDarkMode} />}
            {activeTab === 'invoices' && <InvoiceList bookings={bookings} clients={clients} isDarkMode={isDarkMode} />}
            {activeTab === 'statements' && <StatementView clients={clients} bookings={bookings} transactions={transactions} defaultClientId={selectedClientId} isDarkMode={isDarkMode} />}
            {activeTab === 'forecast' && <Forecast bookings={bookings} isDarkMode={isDarkMode} />}
            {activeTab === 'accounts' && <TransactionList transactions={transactions} stats={stats} onAddTransaction={addTransaction} isDarkMode={isDarkMode} />}
            {activeTab === 'ai' && <AIChat bookings={bookings} transactions={transactions} isDarkMode={isDarkMode} />}
          </div>
