      <div className="flex items-start justify-between relative z-10 mb-4">
        <div className={`p-4 rounded-[22px] bg-gradient-to-br ${themes[color]} text-white shadow-lg`}>
          {React.cloneElement(icon, { size: 24 })}
        </div>
        <div className={`flex items-center gap-1 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${isDarkMode ? 'bg-white/5 text-slate-400' : 'bg-slate-100 text-slate-500'}`}>
          {trend}
