                      </div>
                      <div>
                        <input placeholder="Destination (LHR)" value={formData.to} onChange={e => setFormData({...formData, to: e.target.value.toUpperCase()})} className={`w-full px-6 py-4 border-2 rounded-2xl font-bold text-xs uppercase ${isDarkMode ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-100'}`} />
