                 <div className="col-span-1">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-3">Selling Quote (৳)</label>
                   <input required type="number" placeholder="0.00" value={formData.amount || ''} onChange={e => setFormData({...formData, amount: Number(e.target.value)})} className={`w-full px-6 py-4 border-2 rounded-2xl font-black text-lg outline-none transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700 text-indigo-400' : 'bg-indigo-50 border-indigo-100 text-indigo-700'}`} />
