                 <div className="col-span-1">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-3">Internal Cost (৳)</label>
                   <input required type="number" placeholder="0.00" value={formData.cost || ''} onChange={e => setFormData({...formData, cost: Number(e.target.value)})} className={`w-full px-6 py-4 border-2 rounded-2xl font-black text-lg outline-none transition-all ${isDarkMode ? 'bg-slate-800 border-slate-700 text-rose-400' : 'bg-rose-50 border-rose-100 text-rose-700'}`} />
                 </div>
               </div>

               <div className="flex gap-4 pt-6">
                 <button type="button" onClick={() => setShowModal(false)} className={`flex-1 py-5 text-[10px] font-black uppercase tracking-widest rounded-[28px] transition-all ${isDarkMode ? 'bg-slate-800 text-slate-400' : 'bg-slate-100 text-slate-500'}`}>Abort</button>
                 <button type="submit" className="flex-1 py-5 vibrant-gradient text-white text-[10px] font-black uppercase tracking-widest rounded-[28px] shadow-2xl shadow-indigo-500/40 active:scale-95 transition-all">Synchronize Entry</button>
