import React, { useState, useEffect, useMemo } from 'react';
import { 
  LayoutDashboard, 
  Ticket, 
  Receipt, 
  Users, 
  Settings, 
  Plus, 
  TrendingUp, 
  CreditCard, 
  MessageSquareText,
  Search,
  ChevronRight,
  Menu,
  X,
  Sun,
  Moon,
  BarChart3,
  DownloadCloud,
  Plane,
  FileText,
  History,
  Bell
} from 'lucide-react';
import { Booking, BookingStatus, Transaction, TransactionType, Client } from './types';
import Dashboard from './components/Dashboard';
import BookingList from './components/BookingList';
import TransactionList from './components/TransactionList';
import ClientList from './components/ClientList';
import AIChat from './components/AIChat';
import Forecast from './components/Forecast';
import InvoiceList from './components/InvoiceList';
import StatementView from './components/StatementView';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'bookings' | 'accounts' | 'ai' | 'clients' | 'forecast' | 'invoices' | 'statements'>('dashboard');
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(window.innerWidth > 1024);
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('darkMode');
    return saved ? JSON.parse(saved) : false;
  });

  useEffect(() => {
    localStorage.setItem('darkMode', JSON.stringify(isDarkMode));
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    const handleResize = () => {
      if (window.innerWidth <= 1024) setSidebarOpen(false);
      else setSidebarOpen(true);
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isDarkMode]);

  const [clients, setClients] = useState<Client[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);

  const stats = useMemo(() => {
    const totalIncome = transactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalExpense = transactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    const netProfit = totalIncome - totalExpense;
    const pendingCount = bookings.filter(b => b.status === BookingStatus.PENDING).length;

    return { 
      totalSales: totalIncome, 
      totalCost: totalExpense, 
      netProfit: netProfit, 
      pendingInvoices: pendingCount 
    };
  }, [transactions, bookings]);

  const addBooking = (newBooking: Omit<Booking, 'id'>) => {
    const id = Math.random().toString(36).substr(2, 9);
    setBookings(prev => [...prev, { ...newBooking, id }]);

    const transId = 't' + Math.random().toString(36).substr(2, 5);
    setTransactions(prev => [...prev, {
      id: transId,
      date: new Date().toISOString().split('T')[0],
      category: `${newBooking.type} Sale`,
      amount: newBooking.amount,
      type: TransactionType.INCOME,
      bookingId: id,
      reference: `BOOKING-${id}`
    }]);
  };

  const addTransaction = (newTransaction: Omit<Transaction, 'id'>) => {
    const id = 't' + Math.random().toString(36).substr(2, 7);
    setTransactions(prev => [ { ...newTransaction, id }, ...prev ]);
  };

  const addClient = (newClient: Omit<Client, 'id' | 'createdAt'>) => {
    const id = 'c' + Math.random().toString(36).substr(2, 9);
    setClients(prev => [...prev, { ...newClient, id, createdAt: new Date().toISOString() }]);
  };

  const updateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
  };

  const navigateToStatement = (clientId: string) => {
    setSelectedClientId(clientId);
    setActiveTab('statements');
    if (window.innerWidth <= 1024) setSidebarOpen(false);
  };

  const menuItems = [
    { id: 'dashboard', label: 'Terminal Core', icon: <LayoutDashboard /> },
    { id: 'clients', label: 'Profiles', icon: <Users /> },
    { id: 'bookings', label: 'Inventory', icon: <Ticket /> },
    { id: 'invoices', label: 'Billing', icon: <FileText /> },
    { id: 'statements', label: 'Ledger', icon: <History /> },
    { id: 'forecast', label: 'AI Oracle', icon: <BarChart3 /> },
    { id: 'accounts', label: 'Finance', icon: <CreditCard /> },
    { id: 'ai', label: 'Ask Gemini', icon: <MessageSquareText /> },
  ];

  return (
    <div className={`flex h-screen overflow-hidden transition-colors duration-500 ${isDarkMode ? 'bg-[#020617] text-slate-100' : 'bg-[#f8faff] text-slate-900'}`}>

      {/* Mobile Sidebar Overlay */}
      <div 
        className={`fixed inset-0 bg-black/40 z-[60] lg:hidden transition-opacity duration-300 ${isSidebarOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
        onClick={() => setSidebarOpen(false)}
      />

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] transition-all duration-500 transform ${isSidebarOpen ? 'translate-x-0 w-72' : '-translate-x-full lg:translate-x-0 lg:w-24'} ${isDarkMode ? 'bg-slate-900/90 border-slate-800' : 'bg-white border-slate-100'} glass-panel border-r flex flex-col`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="vibrant-gradient p-2.5 rounded-2xl shadow-xl shadow-indigo-500/20">
              <Plane className="text-white w-6 h-6 rotate-45" />
            </div>
            {isSidebarOpen && (
              <div className="animate-in fade-in slide-in-from-left-2 duration-300">
                <h1 className="font-black text-xl tracking-tighter">B2C <span className="text-indigo-600">TRAVEL</span></h1>
              </div>
            )}
          </div>
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-3 rounded-2xl bg-slate-100 dark:bg-slate-800">
            <X size={20} />
          </button>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4 overflow-y-auto no-scrollbar">
          {menuItems.map(item => (
            <button 
              key={item.id}
              onClick={() => {
                setActiveTab(item.id as any);
                if (window.innerWidth <= 1024) setSidebarOpen(false);
              }} 
              className={`w-full flex items-center gap-4 px-4 py-4 rounded-3xl transition-all duration-300 group relative ${
                activeTab === item.id 
                  ? 'vibrant-gradient text-white shadow-xl shadow-indigo-500/20' 
                  : isDarkMode ? 'text-slate-400 hover:bg-slate-800/50 hover:text-white' : 'text-slate-500 hover:bg-indigo-50 hover:text-indigo-600'
              }`}
            >
              <span className={`${activeTab === item.id ? 'text-white' : 'text-slate-400 group-hover:text-indigo-600'} transition-colors`}>
                {React.cloneElement(item.icon as any, { size: 22 })}
              </span>
              {isSidebarOpen && <span className="font-bold text-[10px] uppercase tracking-[0.2em]">{item.label}</span>}
              {!isSidebarOpen && activeTab === item.id && (
                <div className="absolute left-0 w-1.5 h-6 bg-white rounded-r-full"></div>
              )}
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-slate-100 dark:border-slate-800">
           <button 
            onClick={() => setIsDarkMode(!isDarkMode)} 
            className={`w-full flex items-center gap-4 p-4 rounded-3xl transition-all ${isDarkMode ? 'bg-slate-800 text-amber-400 shadow-inner' : 'bg-slate-100 text-indigo-600 shadow-inner'}`}
          >
            {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
            {isSidebarOpen && <span className="text-[10px] font-black uppercase tracking-widest">{isDarkMode ? 'Solar Shift' : 'Night Shift'}</span>}
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className={`h-24 ${isDarkMode ? 'bg-slate-950/80 border-slate-800' : 'bg-white/80 border-slate-100'} glass-panel border-b flex items-center justify-between px-6 md:px-12 shrink-0 z-40 transition-colors`}>
          <div className="flex items-center gap-4">
             <button onClick={() => setSidebarOpen(true)} className={`lg:hidden p-3 rounded-2xl transition-colors ${isDarkMode ? 'text-slate-400 bg-slate-900' : 'text-slate-500 bg-slate-100'}`}>
               <Menu size={22} />
             </button>
             <div className="hidden sm:block">
                <h2 className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.4em] mb-1">Operational Environment</h2>
                <div className="flex items-center gap-2">
                   <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                   <p className="text-xs font-bold truncate">Terminal v2.5.0: Logged as Principal Admin</p>
                </div>
             </div>
          </div>

          <div className="flex items-center gap-4">
            <button onClick={() => setActiveTab('bookings')} className="cyan-gradient text-white px-6 py-3 rounded-2xl flex items-center gap-2 hover:scale-[1.03] active:scale-95 transition-all text-[11px] font-black shadow-lg shadow-cyan-500/20">
              <Plus size={18} className="stroke-[3]" />
              <span className="hidden sm:inline uppercase tracking-widest">Execute Task</span>
            </button>
            <div className="h-10 w-[1px] bg-slate-200 dark:bg-slate-800 mx-2 hidden sm:block"></div>
            <div className="w-12 h-12 rounded-2xl vibrant-gradient p-[2px] shadow-lg">
              <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Felix" alt="User" className={`w-full h-full rounded-[14px] bg-white border-2 ${isDarkMode ? 'border-slate-900' : 'border-white'}`} />
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-12 no-scrollbar z-10">
          <div className="max-w-7xl mx-auto space-y-6">
            {activeTab === 'dashboard' && <Dashboard stats={stats} bookings={bookings} isDarkMode={isDarkMode} />}
            {activeTab === 'clients' && <ClientList clients={clients} bookings={bookings} onAdd={addClient} onUpdate={updateClient} onNavigateToStatement={navigateToStatement} isDarkMode={isDarkMode} />}
            {activeTab === 'bookings' && <BookingList bookings={bookings} clients={clients} onAdd={addBooking} isDarkMode={isDarkMode} />}
            {activeTab === 'invoices' && <InvoiceList bookings={bookings} clients={clients} isDarkMode={isDarkMode} />}
            {activeTab === 'statements' && <StatementView clients={clients} bookings={bookings} transactions={transactions} defaultClientId={selectedClientId} isDarkMode={isDarkMode} />}
            {activeTab === 'forecast' && <Forecast bookings={bookings} isDarkMode={isDarkMode} />}
            {activeTab === 'accounts' && <TransactionList transactions={transactions} stats={stats} onAddTransaction={addTransaction} isDarkMode={isDarkMode} />}
            {activeTab === 'ai' && <AIChat bookings={bookings} transactions={transactions} isDarkMode={isDarkMode} />}
          </div>
        </div>
      </main>
    </div>
  );
};

