const StatusBadge = ({ status, isDarkMode }: { status: BookingStatus, isDarkMode?: boolean }) => {
  const configs = {
    [BookingStatus.CONFIRMED]: { icon: <CheckCircle2 size={12} />, styles: isDarkMode ? 'bg-emerald-500/10 text-emerald-500' : 'bg-emerald-50 text-emerald-600' },
    [BookingStatus.PENDING]: { icon: <AlertCircle size={12} />, styles: isDarkMode ? 'bg-amber-500/10 text-amber-500' : 'bg-amber-50 text-amber-600' },
    [BookingStatus.CANCELLED]: { icon: <XCircle size={12} />, styles: isDarkMode ? 'bg-rose-500/10 text-rose-500' : 'bg-rose-50 text-rose-600' },
  };
  const config = configs[status];
  return (
    <span className={`inline-flex items-center gap-1.5 px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${config.styles}`}>
      {config.icon}
      {status === 'PENDING' ? 'UNPAID' : status}
    </span>
  );
};

